INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2010,34,'马原·哲学','结合材料回答问题：
早年，梅兰芳与人合演《断桥》，也就是《白蛇传》，剧情是白娘子和许仙两个人悲欢离合的爱情故事，梅兰芳在剧中饰演白娘子。剧中，白娘子有一个动作就是面对负心的丈夫许仙追赶、跪在地上哀求她的时候，她爱恨交加、五味杂陈，就用一根手指头去戳许仙的脑门儿，不想，梅兰芳用力过大，跪在那里扮演许仙的演员毫无防备地向后仰去。这是剧情里没有设计的动作，可能是梅兰芳入戏太深，把对许仙的恨全都聚集在了手指头上，才造成了这样的失误。眼见许仙就要倒地，怎么办?梅兰芳下意识地用双手去扶许仙。许仙是被扶住了，没有倒下。可梅兰芳马上意识到，我是白娘子，他是负心郎许仙，我去扶他不合常理，这戏不是演砸了吗?大师到底是大师，梅兰芳随机应变，在扶住他的同时，又轻轻地推了他一下。所以，剧情就由原来的一戳变成了一戳、一扶和一推，更淋漓尽致地表现出了白娘子对许仙爱恨交织的复杂心情。这个动作，把险些造成舞台事故的错误演得出神入化，得到了大家的认可。从此，在以后的演出中，梅兰芳就沿用了这个动作，而且，其他剧种也都移植采用了这个动作处理，这个动作成了经典之作。
由此可见，不仅在舞台上，在各行各业，在各个岗位，在工作中，在生活中，无论是大师还是普通人，失误和错误是难免的，关键是出现失误和错误以后怎么去对待，怎么去处理。处理不当，会酿成事故，导致全盘失败;处理得当，能败中取胜，化腐朽为神奇。
(1)为什么“无论是大师还是普通人，失误和错误是难免的”?
(2)梅兰芳为什么能“把险些造成舞台事故的错误”变为成功的“经典之作”?
(3)当我们在认识和实践活动中出现错误或失败该怎样对待和处理?','["为什么“无论是大师还是普通人，失误和错误是难免的”?","梅兰芳为什么能“把险些造成舞台事故的错误”变为成功的“经典之作”?","当我们在认识和实践活动中出现错误或失败该怎样对待和处理?"]','["认识受实践水平、立场、知识结构等主客观条件制约，人对复杂事物的认识不可能一次完成，因而失误和错误难以避免。","真理与谬误相比较而存在、相斗争而发展，二者在一定条件下可以相互转化。","梅兰芳能成功是因为他尊重舞台实践的客观情境，发挥主观能动性，抓住矛盾转化的条件，把失误转化为艺术创造。","对待错误应科学分析其产生的原因，总结经验教训，把握转化条件，变失败为成功的先导。"]','认识的反复性与无限性',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2010,35,'形势与政策','结合材料回答问题：
材料概述：材料回顾新中国成立60年特别是改革开放以来民生事业的显著成就（废除农业税、城乡住房与储蓄水平大幅提高等），同时指出就业、教育、医疗、住房、社会保障等领域仍存在突出问题，党的十七大对加快推进以改善民生为重点的社会建设作出部署。
(1)为什么在经济发展的同时要加快推进以改善民生为重点的社会建设?
(2)如何推进以改善民生为重点的社会建设?','["为什么在经济发展的同时要加快推进以改善民生为重点的社会建设?","如何推进以改善民生为重点的社会建设?"]','["改善民生是社会主义本质要求的体现，是落实科学发展观、实现社会公平正义与全面小康的需要。","经济发展与社会建设相互支撑，只有民生改善才能扩大内需、促进社会和谐稳定。","推进民生建设要优先发展教育、实施扩大就业的发展战略、深化收入分配制度改革。","要加快建立覆盖城乡居民的社会保障体系，建立基本医疗卫生制度，完善社会管理。"]','健全保障和改善民生制度体系',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2010,36,'史纲','结合材料回答问题：
材料概述：材料1记述1949年10月1日开国大典盛况，宋庆龄在天安门城楼上望着孙中山画像感慨“孙中山的努力终于结了果实”；材料2引述纪念新中国成立60周年的评论，指出中华人民共和国的成立使中华民族从此进入了发展进步的历史新纪元。
(1)如何理解宋庆龄所说的“孙中山的努力终于结了果实”?
(2)为什么说中华人民共和国的成立标志着“中华民族从此进入了发展进步的历史新纪元”','["如何理解宋庆龄所说的“孙中山的努力终于结了果实”?","为什么说中华人民共和国的成立标志着“中华民族从此进入了发展进步的历史新纪元”"]','["孙中山领导的辛亥革命提出振兴中华，但未能改变中国半殖民地半封建的社会性质和人民的悲惨境遇。","中国共产党继承并发展了孙中山的革命事业，完成了反帝反封建的民主革命任务，建立了新中国，故说其努力“结了果实”。","新中国的成立结束了帝国主义、封建主义和官僚资本主义的统治，人民成为国家的主人。","新中国的成立为实现国家富强、民族复兴和人民幸福扫清了障碍、创造了前提，中华民族由此进入发展进步的历史新纪元。"]','中华人民共和国成立的意义',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2010,37,'思修法基','结合材料回答问题：
材料
交通环境是由人、车、路构成的公共生活领域之一，目前，我国机动车拥有量已超过1.78亿辆，拥有驾照的公民已超过1.3亿人。由此带来一系列的交通安全问题，引发社会公众强烈反响。
下列是有关交通问题的一些调查数据：
《人民日报》关于不文明开车行为及其原因的调查
个人反感的不文明开车行为
不文明开车的原因
斑马线不减速让行 2156票
乱停车挡道 1687票
司机素质普遍有待提高 2269票
夜间会车不关远光灯 2045票
胡乱鸣笛 1412票
跟风，随大流 1469票
“加塞儿”，并线不打灯 1928票
司机出口成“脏” 1076票
行人不文明导致司机不文明 757票
雨天不减速水溅路人 1902票
抢黄灯 944票
因车多路堵无法文明驾驶 464票
某市交管局一年中查处交通违章的数据统计
全年查处交通违章总数
207万起
比例：100%
其中：机动车违章
112.2万起
54.2%
非机动车违章
80.5万起
38.9%
行人违章
14.3万起
6.9%
有专家指出，道路交通上普遍存在的交通不文明现象看似个人的私事，但却折射出某些公民在公共生活领域社会公德和法律意识的缺失。要构建文明出行风尚，既是道德呼唤，也是法律要求。
回答问题：
(1)为什么文明出行“既是道德呼唤，也是法律要求”?
(2)我们应如何从自身做起，构建文明的公共生活秩序?','["为什么文明出行“既是道德呼唤，也是法律要求”?","我们应如何从自身做起，构建文明的公共生活秩序?"]','["公共生活需要道德与法律共同规范，二者互为补充、相辅相成。","文明出行关系公共秩序与他人生命财产安全，既属于社会公德的基本要求，也是道路交通安全法等法律的强制要求。","道德为法律提供价值基础，法律为道德提供制度保障，交通不文明行为折射公德意识与法律意识的双重缺失。","个人应自觉学法守法，增强公德意识与规则意识，从遵守交通规则等身边小事做起，共同营造文明的公共生活秩序。"]','社会公德、职业道德、家庭美德、个人品德',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2010,38,'形势与政策','结合材料回答问题：
材料一
从2009年11月23日起，一则时长30秒“以中国制造世界合作”为主题的广告在美国有线电视新闻网(CNN)正式播出。该广告由中国商务部会同4家中国行业协会共同委托制作，被认为是中国政府的首个品牌宣传活动，接下来还计划在包括北美、欧洲等中国的主要贸易对象地区播出。
广告围绕“中国制造 世界合作”这一主题，强调中国企业为生产高质量的产品，正不断与海外各国公司加强合作。广告中展示了一系列带有“中国制造”标签的产品，例如，一个类似ipod的mp3播放器上用英文标注“在中国制造，但我们使用来自硅谷的软件”，一双运动鞋和一套衣服上标注有“在中国制造，但我们的设计来自于法国”，一台冰箱上写着“中国制造，但我们的采用欧洲风格”。
广告在创意上独树一帜，从引导世界受众重新认识畅销全球的中国产品入手，能够启发世界各地的消费者对“中国制造”和全球贸易的重新思考，从而逐渐抛弃对“中国制造”的偏见。
材料二
在美国有线电视新闻网热播的一则“携手中国制造”为主题的广告引发的关注和反响正在发酵。有分析人士认为，在当前金融危机阴霾尚未散去，贸易保护主义有所抬头的背景下，主动出击展示国家形象，是一次很好的尝试，有利于提升中国的软实力。
有评论认为，近年来中国经济实力崛起，如何建立国际形象成为当务之急，政府近期启动了国际公关战略，继新华社，《人民日报》等中央媒体率先向世界发声之后，国家形象广告或许会成为提升国家软实力和对外形象的新渠道。还有人认为，中国早前一些产品安全事件令世界关注，现在希望能通过在全球投放广告推广“中国制造”以提升在国际上的形象，广告中出现的法国设计、硅谷技术等字样，说明中国目前还处于产业链的低端，它继续把中国定义为世界工厂，因此，令消费者认为中国还只是产品的制造商，现在是从“中国制造”的地位上升为“中国创造”的时候了。
问题：
(1)“中国制造，世界合作”的广告说明了什么?
(2)为什么说现在是从“中国制造”的地位上升为“中国创造”的时候了?','["“中国制造，世界合作”的广告说明了什么?","为什么说现在是从“中国制造”的地位上升为“中国创造”的时候了?"]','["广告表明中国制造已深度融入全球产业链，中国产品是国际分工合作的产物，体现了中国开放、合作、共赢的形象。","它有助于消除外界对中国制造的误解，说明经济全球化条件下各国利益相互交织。","长期处于产业链低端使中国面临资源环境压力和贸易摩擦，转变发展方式势在必行。","提升自主创新能力、培育自主品牌、发展创新型国家，是从“中国制造”走向“中国创造”的必然要求。"]','高水平对外开放',1,0);
DELETE FROM real_subjective WHERE year=2011;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2011,34,'马原·哲学','结合材料回答问题：
人类每天都在产生垃圾、垃圾总量一天比一天多，由此带来的问题非常棘手，不产生垃圾是不可能的，既然如此，那就退而求其次，倡导大家减少垃圾，然而减到多少才是少?这里并没有一个标准，而且从总体上看，生产和消费必然产生垃圾，减少垃圾很可能抑制生产和消费，接着往后退，把垃圾收集起来填埋或焚烧，但填埋只是把垃圾从地上转移到地下，既与人争地，也有再次污染土壤和水源的隐患，焚烧不过是把污染从地上转移到空中，产生二恶英等有害物质。
于是，人们进一步追问：还有没有比填埋、焚烧更好的出路?一句“垃圾是放错地方的资源”让人茅塞顿开，垃圾可以回收利用，乃再生资源。但变废为“宝”前提是垃圾的有效投放—别把垃圾放错了地方，何谓放错?到处乱扔是放错，不同的垃圾搅混在一起也是放错，不同的垃圾只有不同的地方放，才能实现资源的价值，投放避免不了要填埋，焚烧那些没有利用价值的垃圾，也得把他们分出来。
垃圾分类举手之劳换出绿色，好处多多不言而喻，但如何让人们乐而为久，今年5月起，上海开始普遍推广新的垃圾分类理念，开展以“提升更绿色的上海”为主题的“绿色账户活动”何为“绿色账户”?这是居民对垃圾分类回收，积分换取环保小礼品：再生纸笔记本，绿色小植物，环保手电筒...。.上海推出"绿色账户”实现模式，办法是可以想出来的，关键是愿不愿意琢磨，中国的垃圾问题不比哪个国家小，我们只呢“没有退路就多想出路”。
(1)从实践是人和自然关系的基础的角度说明为什么“垃圾是放错地方的资源?”
(2)运用矛盾分析方法说明“没有退路就多想出路”','["从实践是人和自然关系的基础的角度说明为什么“垃圾是放错地方的资源?”","运用矛盾分析方法说明“没有退路就多想出路”"]','["实践是人与自然关系的基础和中介，人通过实践改造自然，也必须承担合理调节人与自然物质变换的责任。","垃圾是否是资源不是纯自然属性，而取决于人的实践能力与利用方式，通过科学处理可实现废物向资源的转化。","矛盾双方对立统一并在一定条件下相互转化，“没有退路”这种不利条件可以转化为激发创新的动力。","矛盾分析法要求在困境中积极创造条件促成转化，多想出路、化危为机。"]','对立统一规律',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2011,35,'毛中特','结合材料回答问题：
材料概述：材料1引述经济学家、原民建中央主席成思危对我国政党制度的比喻——西方政党制度是“打橄榄球”，一定要把对方压倒，我国政党制度是“唱大合唱”，各民主党派与中国共产党围绕共同目标合作共事；材料2介绍各民主党派成员在国家机关任职和参政议政的情况。
(1)从“打橄榄球”和“唱大合唱”的形象比较中，说明我国政党制度的特点和优点。
(2)我国各民主党派在社会主义建设中如何发挥参政议政的作用?','["从“打橄榄球”和“唱大合唱”的形象比较中，说明我国政党制度的特点和优点。","我国各民主党派在社会主义建设中如何发挥参政议政的作用?"]','["我国实行中国共产党领导的多党合作和政治协商制度，各政党像“唱大合唱”一样围绕共同目标协调一致，而非“打橄榄球”式的相互对抗。","其特点是共产党领导、多党派合作，共产党执政、多党派参政，各民主党派是亲密友党而非在野党、反对党。","这一制度能够广泛集中民智、反映各方利益，实现集中统一领导与广泛民主协商的统一，保持政治稳定。","各民主党派通过参加国家政权、参与重大方针政策的协商，履行政治协商、民主监督、参政议政职能，为社会主义建设建言献策。"]','全过程人民民主',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2011,36,'史纲','结合材料回答问题：
材料概述：材料1摘自《毛泽东选集》：十月革命唤醒了中国人，中国产生了共产党，这是开天辟地的大事变；材料2介绍党史著作《苦难辉煌》的追问——中国共产党从几十人的小党发展为大党、由弱到强，力量来自哪里？作者的回答是：我们拥有一批不为钱、不为官、不怕苦、不怕死，只为胸中的主义和心中的信仰的真人。
(1)为什么说中国共产党的成立“是开天辟地的大事变?
(2)结合中国共产党成立以来中国社会变革的历程，说明“主义”和“信仰”是怎样成为“力量”的?','["为什么说中国共产党的成立“是开天辟地的大事变?","结合中国共产党成立以来中国社会变革的历程，说明“主义”和“信仰”是怎样成为“力量”的?"]','["中国共产党的成立使中国革命有了坚强的领导核心、科学的指导思想和崭新的奋斗目标，中国革命的面貌焕然一新，故称开天辟地的大事变。","党把马克思主义与中国实际相结合，找到了新民主主义革命道路，完成了民族独立和人民解放的历史任务。","社会主义制度的建立和改革开放的成功实践证明，科学的“主义”一旦与人民群众相结合，就转化为改造世界的强大物质力量。","坚定的信仰凝聚起全党全国人民的意志，成为战胜艰难险阻、推动社会变革的精神支柱。"]','中国共产党的成立',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2011,37,'思修法基','结合材料回答问题：
材料概述：材料讲述鞍钢矿山公路管理员郭明义的事迹：他以雷锋为人生榜样，连续15年每天提前2小时上班，20年间55次无偿献血，16年间为希望工程和特困生捐款12万元，自己一家却住在40平方米的旧房里；他说帮助别人改变命运比自己活得舒服更幸福，其事迹被誉为“简单中的伟大”。
(1)如何理解“给人温暖就是给自己幸福”?
(2)为什么说郭明义的先进事迹是“简单中的伟大”?','["如何理解“给人温暖就是给自己幸福”?","为什么说郭明义的先进事迹是“简单中的伟大”?"]','["人生的自我价值与社会价值辩证统一，为社会和他人作贡献是实现自我价值的基础。","给人温暖体现了服务人民、奉献社会的人生追求，在奉献中获得的精神满足是更高层次的幸福。","郭明义的事迹平凡而持久，把助人为乐融入日常工作生活，在点滴小事中长期坚守，故为“简单中的伟大”。","这启示我们应从平凡小事做起，在为他人和社会的奉献中创造有意义的人生。"]','人生观的主要内容',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2011,38,'形势与政策','结合材料回答问题：
金融危机发生后，某些西方国家的政要、媒体经常发表关于中国的言论，有“独秀”或“救世”之说、也有“责任”之论……林林总总，用词翻新。人们可看到一白一红“两张脸”：唱红脸者夸大中国的经济表现，动辄将一切不符合实际加诸中国，仿佛中国真的是世界经济的救世主。唱白脸者却将国际金融危机，全球失衡等责任归到中国头上，无论是明“捧”实“压”，还是借“批”卸“责”，万变不离其宗的都是鼓噪“中国责任论”。这既暴露出他们所谓“中国责任”的用心，也反映出其对“真实中国”的误解。
(1)针对材料所反映的西方某些人士对中国的“捧”与“批”，谈谈什么是“真实的中国”以及中国的“责任”是什么。','["针对材料所反映的西方某些人士对中国的“捧”与“批”，谈谈什么是“真实的中国”以及中国的“责任”是什么。"]','["真实的中国是一个人口多、底子薄的世界最大发展中国家，虽然经济总量大，但人均水平低、发展不平衡问题突出。","中国既取得了巨大发展成就，也面临转变发展方式、改善民生等艰巨任务，不能被“捧”与“批”所左右。","中国的责任首先是办好自己的事情，实现自身发展，这本身就是对世界的重大贡献。","中国作为负责任大国，在力所能及范围内承担相应国际义务，推动世界和平与共同发展，但不承担超越发展阶段的“责任”。"]','中国特色大国外交与百年变局',1,0);
DELETE FROM real_subjective WHERE year=2012;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2012,34,'马原·哲学','结合材料回答问题：
材料概述：材料1讲述丹麦物理学家雅各布·博尔打碎花瓶后，通过对碎片按重量分类统计发现碎片重量之间存在倍数关系，提出可用于恢复文物、陨石等不知原貌物体的“碎花瓶理论”；材料2介绍一堂书法课上老师引导学生把写坏的字改造为新的艺术形态，并引出“这个世界上没有真正的错误，只有被忽略的智慧”的观点。
(1)从打碎花瓶这一现象中所概括出的“碎花瓶理论”为什么能帮助人们恢复文物、陨石等不知原貌的物体?
(2)如何理解“这个世界上没有真正的错误，只有被忽略的智慧”?
(3)上述两例对我们增强创新意识有何启示?','["从打碎花瓶这一现象中所概括出的“碎花瓶理论”为什么能帮助人们恢复文物、陨石等不知原貌的物体?","如何理解“这个世界上没有真正的错误，只有被忽略的智慧”?","上述两例对我们增强创新意识有何启示?"]','["世界是物质的，事物的运动变化有其客观规律，花瓶破碎的碎片分布服从统计规律，人可以认识和利用这种规律恢复原貌。","意识具有能动性，人能够透过偶然现象把握必然联系，将“错误”中蕴含的规律性认识转化为有用的智慧。","所谓“没有真正的错误”，是指失败与错误中往往包含尚未被认识的规律和价值，关键在于善于发现与总结。","增强创新意识要求解放思想、突破常规思维，善于从偶然中发现必然、从失误中捕捉机遇。"]','必然性与偶然性',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2012,35,'毛中特','结合材料回答问题：
材料1
十一届全国人大常委会第二十次会议初次审议的《中华人民共和国个人所得税法修正案(草案)》将个人所得税免征额由现行的每月2000元调至3000元。随后，全国人大常委会通过中国人大网向社会公开征求意见，共收到82707人提出的意见23万余件。82536人对个人所得税起征点发表意见，其中要求提高起征点的意见高达83%。
2011年5月10日和20日，全国人大法律委员会、财政经济委员会和全国人大常委会法制工作委员会联合召开座谈会，还分别听取11位专家和16位来自不同地区、不同职业、不同收入群体具有一定代表性的社会公众对草案的意见。
6月27日， 个法修正案草案再次提交全国人大常委会审议时，二审稿对3000元起征点仍未作修改。在审议过程中，有委员表示，网上征求意见中，要求提高起征点的占83%。对如此集中的意见，草案未充分回应，很难向公众解释清楚。更有委员指出，个人所得税法不是5000元、3000元的问题，而是如何更认真地对待群众意见和老百姓的关注问题。
6月30日，全国人大常委会第二十一次会议以134票赞成、6票反对、11票弃权，决定对《中华人民共和国个人所得税法》作如下修改：一、第三条第一项修改为：“工资、薪金所得，适用超额累进税率，税率为百分之三至百分之四十五。”二、第六条第一款第一项修改为：“工资、薪金所得，以每月收入额减除费用三千五百元后的余额，为应纳税所得额。”
摘编自 中国人大网(2011年6月30日、2011年7月1日)
材料2
此次个人所得税法的修改将在社会生活中发挥积极作用。首先，大幅度减轻中低收入纳税群体的负担。一方面，减除费用标准由2000元提高到3500元后，纳税人纳税负担普遍减轻。工薪收入者纳税面调整后，纳税人数由约8400万人减至约2400万人。另一方面，通过调整工薪所得税率结构，使绝大部分工薪所得纳税人在享受提高减除费用标准的同时，进一步减轻税负。这两个措施是不一样的，减除费用的提高是普惠，通过税率级距调整进行结构性的变化，是使中低收入纳税群体在减税的基础上进一步减税。此外，适当扩大低档税率和最高档税率的适用范围，使低税率向大部分纳税人倾斜。其次，适当加大对高收入者的调节力度。实行提高工薪所得减除费用标准和调整工薪所得税率结构变化联动，能够使一部分高收入者在抵消减除费用标准提高得到的减税好处以后，适当增加一些税负。
摘编自 中国人大网(2011年6月30日)
(1)此次个税法修改过程如何体现了中国特色社会主义民主?
(2)结合此次个税法的修改，分析当前我国收入分配制度改革的趋向和合理调整收入分配格局的要求。','["此次个税法修改过程如何体现了中国特色社会主义民主?","结合此次个税法的修改，分析当前我国收入分配制度改革的趋向和合理调整收入分配格局的要求。"]','["个税法修改经过全国人大常委会审议并向全社会公开征求意见，广泛吸纳民意，体现了党的领导、人民当家作主与依法治国的有机统一。","立法过程中的公开征求意见和根据民意修改条款，体现了社会主义民主的广泛性和真实性。","个税免征额提高和税率级距调整表明收入分配改革着力减轻中低收入者负担、加大对高收入的调节。","合理调整收入分配格局要坚持按劳分配为主体、多种分配方式并存，提高居民收入在国民收入分配中的比重，通过税收等再分配手段促进社会公平。"]','全过程人民民主',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2012,36,'史纲','结合材料回答问题：
材料1
“余维欧美之进化，凡以三大主义：曰民族、曰民权、曰民生。罗马之亡，民族主义兴，而欧洲各国以独立。洎自帝其国，威行****，在下者不堪其苦，则民权主义起。十八世纪之末，十九世纪之初，****仆而立宪政体殖焉。世界开化，人智益蒸，物质发舒，百年锐于千载，经济问题继政治问题之后，则民生主义跃跃然动，二十世纪不得不为民生主义之擅场时代也。是三大主义皆基本于民，递 变易，而欧洲之人种胥治化焉。”
“中国数千年来都是君主****政体，这种政体，不是平等自由的国民所堪受的，要去这种政体，不是专靠民族革命可以成功……我们推到满洲政府，从驱除满人那一面说是民族革命，从颠覆君主政体那一面说是政治革命，并不是把来分作两次去做。讲到那政治革命的结果，是建立民主政体立宪政体。照现在这样的政治论起来，就算汉人为君主，也不能是革命。”
摘自《孙中山全集》第一卷
材料2
“一百年以来,我们的先人以不屈不挠的斗争反对内外压迫者,从来没有停止过,其中包括伟大的中国革命先行者孙中山先生所领导的辛亥革命在内,我们的先人指示我们,叫我们完成他们的遗志.我们现在是这样做了.我们团结起来,以人民解放战争和人民大革命****了内外压迫者,宣布中华人民共和国成立了.我们的民族将从此列入爱好和平自由的世界各民族的大家庭,以勇敢而勤劳的姿态工作着,创造自己的文明和幸福,同时也促进世界的和平和自由.我们的民族将再也不是一个被人侮辱的民族了,我们已经站起来了.”
摘自《毛泽东文集》第五卷
(1)如何理解“就算汉人为君主，也不能不革命”？
(2)为什么说中国共产党人是孙中山开创的革命事业“最忠实的继承者”？','["如何理解“就算汉人为君主，也不能不革命”？","为什么说中国共产党人是孙中山开创的革命事业“最忠实的继承者”？"]','["孙中山认为专制政体不是平等自由的国民所能忍受的，即使汉人做君主也仍是专制，因此民族革命必须与政治革命并行，推翻君主专制、建立民主共和。","这表明辛亥革命不仅是排满的民族革命，更是反对封建专制制度的政治革命。","中国共产党继承了孙中山反帝反封建、振兴中华的事业，领导人民完成了他未竟的民族独立和人民解放任务。","党在继承中发展，把民主革命推进到新民主主义和社会主义阶段，建立了人民当家作主的新中国，故为其革命事业最忠实的继承者。"]','辛亥革命',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2012,37,'思修法基','结合材料回答问题：
“新年不欠旧年账，今生不欠来生债”，这是孙东林和哥哥孙水林的共同准则。1989年，孙东林与哥哥孙水林一同组建起建筑队伍，开始在北京、河南等地承接建筑工程和装饰工程。此后的20年中，无论遇到什么状况，孙东林从未拖欠过工人的工资。有时工程款不能及时拿到，他四处借钱，也要坚持将工资发放。他说，“诚信，是为人之道，也是立足之本。”
2010年2月9日，在天津承包建筑工程的孙水林，为抢在春节前赶回武汉给先期返乡的农民工发放工资，不顾路途遥远、天气恶劣，连夜赶路千里送薪。不料，2月10日凌晨遭遇车祸，一家五口不幸遇难。得知噩耗，孙东林悲痛不已。为了替哥哥完成遗愿，他带上哥哥车上的26万元钱，连续驱车15小时，返乡代兄为农民工发放工资。两天未合眼的孙东林流着泪眼赶回家中，和老人商议决定，先替哥哥完成遗愿，年前发完工钱再办丧事。他自己垫上6万以后，还差1万多元。这个时候，他们的老母亲拿着1万块现金交到儿子手上。这可是老人家的养老钱呀!
随后，孙家立即让工友互相通知上门领钱。发工资的时候，孙东林和工友们找不到账单，都是凭着一本“良心账”，工友们说多少，孙东林就给多少。腊月二十九晚上，33.6万元工钱全部发完，竟与哥哥遇难前哥俩说过的数额相差无几。69名拿着工钱的工友对孙东林说：“明年我们跟你接着干”。
(1)基于“信义兄弟”这个事例，怎样理解诚信及其道德力量?
(2)在法律关系中，为什么也要坚守诚信?','["基于“信义兄弟”这个事例，怎样理解诚信及其道德力量?","在法律关系中，为什么也要坚守诚信?"]','["诚信是诚实守信、言行一致的道德品质，是公民道德的基本规范和市场经济的基石。","“信义兄弟”接力送薪表明诚信可以超越生死约定，产生感召社会、凝聚人心的道德力量。","诚实信用同时是我国民事法律的基本原则，守约践诺是法律关系主体必须履行的义务。","坚守诚信既靠道德自律，也靠法律他律，二者共同维护公平有序的社会关系。"]','社会主义道德的核心与原则',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2012,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍2011年中国国家形象片《人物篇》在纽约时报广场播放的情况：宣传片汇集各领域杰出代表与感动中国的普通人，向世界展示真实、立体的中国形象；评论认为随着综合国力提升和重大国际活动举办，中国开始步入主动开展公共外交、塑造国家形象的“国家公关时代”。
(1)分析“中国开始步入‘国家公关时代’”的原因。
(2)国家形象宣传对提升中国软实力有何作用?','["分析“中国开始步入‘国家公关时代’”的原因。","国家形象宣传对提升中国软实力有何作用?"]','["随着综合国力和国际地位提升，中国与世界的联系空前紧密，需要主动向世界说明自己、塑造良好国家形象。","国际上对中国的关注与误解并存，“中国威胁论”等杂音要求中国加强国家公关、争取国际话语权。","北京奥运会、上海世博会等重大活动为中国开展公共外交提供了平台和契机。","国家形象宣传有助于增进国际社会对中国的了解与认同，增强中国文化的吸引力和影响力，从而提升国家文化软实力。"]','社会主义文化建设',1,1);
DELETE FROM real_subjective WHERE year=2013;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2013,34,'马原·哲学','结合材料回答问题：
材料概述：材料1讲述教育著作《第56号教室的奇迹》中的故事：一位教师珍藏签名棒球，警告年幼的儿子不能拿来玩却不说明理由，结果儿子把球上“脏字”洗掉，教师由此领悟要“用孩子的眼睛看世界”；材料2介绍一位设计师坚持“设计前把自己想象成老人”，通过换位体验设计出便利老年人的产品，并倡导“用自己的设计改变生活，让生活更美好”。
(1)分析“用孩子的眼睛看世界”和“设计前把自己想象成老人”两事例所体现的认识主体的能动作用。
(2)“用自己的设计改变生活，让生活更美好”对我们从事实践活动有何意义?','["分析“用孩子的眼睛看世界”和“设计前把自己想象成老人”两事例所体现的认识主体的能动作用。","“用自己的设计改变生活，让生活更美好”对我们从事实践活动有何意义?"]','["认识主体具有能动性，主体的立场、经验和思维方式影响认识活动及其结果。","“用孩子的眼睛看世界”“把自己想象成老人”体现了主体自觉转换视角、通过换位体验把握客体真实需要的能动作用。","从实际出发、深入实际调查体验，是获得正确认识的前提。","实践活动应坚持以人为本，把满足人的需要作为设计和创造的出发点，用创新成果改善生活。"]','认识的两次飞跃',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2013,35,'毛中特','结合材料回答问题：
材料概述：材料讲述浙江武义县后陈村因村务财务不透明导致干群矛盾频发，2004年在县纪委推动下建立全国第一个村务监督委员会，制定村务管理和监督两项制度，实现村务全程公开监督；此后村集体资产处置规范有序，多年实现村干部“零违纪”、村民“零上访”，其经验被写入相关法律修订。
(1)后陈村是如何通过制度创新来保障权力在阳光下运行的?
(2)全国第一个村务监督委员会的建立对推进基层民主制度建设有何启示?','["后陈村是如何通过制度创新来保障权力在阳光下运行的?","全国第一个村务监督委员会的建立对推进基层民主制度建设有何启示?"]','["后陈村设立村务监督委员会，使村务决策、财务管理置于专门机构的监督之下，实现了权力运行的公开透明。","通过制度创新把民主选举、民主决策、民主管理、民主监督落到实处，从源头上遏制了腐败。","这启示基层民主建设必须健全权力运行的制约和监督机制，保障群众的知情权、参与权、表达权、监督权。","要尊重群众首创精神，把行之有效的实践经验上升为制度，不断完善基层群众自治制度。"]','全过程人民民主',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2013,36,'史纲','结合材料回答问题：
材料概述：材料1讲述1910年陆士谔在幻想小说《新中国》中梦见上海举办万国博览会、建成大铁桥和地铁，以及孙中山《建国方略》中修建铁路、公路、三峡大坝等设想，这些当年的“梦想”今天都已实现；材料2引述方志敏《可爱的中国》对祖国美好前途的憧憬，以及习近平总书记参观《复兴之路》展览时对中国梦的阐述。
(1)为什么“实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想”?
(2)为什么说“现在我们比历史上任何时期都更接近中华民族伟大复兴的目标”?','["为什么“实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想”?","为什么说“现在我们比历史上任何时期都更接近中华民族伟大复兴的目标”?"]','["近代以来中华民族遭受深重苦难，争取民族独立、人民解放和实现国家富强、人民幸福成为中华民族最伟大的梦想。","民族复兴梦想凝聚了几代中国人的夙愿，体现了中华民族和中国人民的整体利益。","在中国共产党领导下，中国完成新民主主义革命和社会主义革命，开创中国特色社会主义道路，为民族复兴奠定了制度基础和物质基础。","改革开放以来的巨大成就使我国综合国力大幅提升，道路、理论、制度日益完善，因而比历史上任何时期都更接近民族复兴的目标。"]','中国特色社会主义进入新时代',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2013,37,'思修法基','结合材料回答问题：
材料概述：材料讲述杭州图书馆多年坚持向包括乞丐、拾荒者在内的所有读者免费开放，有读者不满，馆长回答“我无权拒绝他们入内阅读，但你有权选择离开”；此事经媒体报道后引发全社会对公共图书馆办馆理念和人文精神的广泛讨论。
(1)从法律角度如何理解“我无权拒绝他们入内阅读，但你有权选择离开”?
(2)图书馆向乞丐和拾荒者免费开放对我们处理人际关系有何启示?','["从法律角度如何理解“我无权拒绝他们入内阅读，但你有权选择离开”?","图书馆向乞丐和拾荒者免费开放对我们处理人际关系有何启示?"]','["公民在法律面前一律平等，乞丐和拾荒者与其他公民一样平等享有利用公共文化设施的权利，图书馆无权拒绝。","其他读者若不满，可以行使自己的选择自由离开，但不能剥夺他人的合法权利。","权利与义务相统一，行使权利时应尊重他人同等的权利。","处理人际关系应坚持平等尊重、宽容互助的原则，学会换位思考，以包容心态对待差异，促进人与人的和谐。"]','法治思维与法律权利义务',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2013,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍2012年前后美国发布防务与安全战略报告、宣布战略重心转向亚太（“亚太再平衡”）的情况：美国加强在亚太的军事部署和同盟体系，拉拢地区国家；材料还引述美国学者与地区舆论对这一战略针对中国、加剧地区紧张的分析评论。
(1)美国将其全球战略重心转向亚太的原因何在?
(2)如何看待美国战略重心东移（亚太再平衡）对中国周边安全环境的影响？','["美国将其全球战略重心转向亚太的原因何在?","如何看待美国战略重心东移（亚太再平衡）对中国周边安全环境的影响？"]','["美国把战略重心转向亚太，根本上是为了维护其全球霸权地位，应对亚太特别是中国崛起带来的力量对比变化。","亚太地区成为世界经济增长中心，美国欲分享地区发展红利并主导地区秩序。","战略东移使中国周边安全环境更加复杂，海洋争端等热点问题升温，地区军事竞争加剧。","应对上中国应坚持和平发展，稳定周边外交，推动构建中美新型大国关系，维护地区和平稳定大局。"]','中国特色大国外交与百年变局',1,1);
DELETE FROM real_subjective WHERE year=2014;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2014,34,'马原·哲学','结合材料回答问题：
材料概述：材料介绍山东某地运用循环经济理念处理秸秆的探索：引进企业以秸秆加鸡粪培育双孢菇，蘑菇渣制成有机肥还田，形成“秸秆—蘑菇—肥料—农田”的大循环，既解决了秸秆焚烧难题，又带动农民增收，“巧用大循环，处理不再难”。
(1)从唯物辩证法的角度分析“巧用大循环，处理不再难”中“巧”在何处？
(2)当你在生活中遇到难题和矛盾时，上述事例对你有何启示？','["从唯物辩证法的角度分析“巧用大循环，处理不再难”中“巧”在何处？","当你在生活中遇到难题和矛盾时，上述事例对你有何启示？"]','["“巧”在运用普遍联系的观点，把畜禽粪污、秸秆等废弃物纳入生态循环链条，实现变废为宝。","体现了矛盾双方在一定条件下相互转化的原理，通过创造条件使“废”转化为“宝”。","坚持系统观念和整体思维，统筹各环节，使局部难题在大循环中得到解决。","启示我们遇到难题时要用联系的、全面的、发展的眼光看问题，善于创造条件促成矛盾转化，在更大系统中寻找解决办法。"]','对立统一规律',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2014,35,'毛中特','结合材料回答问题：
材料概述：材料1回顾1978年改革开放决策曾遭外媒质疑，三十多年后我国经济总量跃居世界第二，同时发展起来后的资源环境约束、社会矛盾等“中国式难题”也随之出现；材料2摘自习近平关于全面深化改革决定的说明，强调改革开放只有进行时、没有完成时。
(1)如何看待改革开放进程中的“中国式奇迹”与“中国式难题”？
(2)运用社会基本矛盾原理分析为什么“改革开放只有进行时、没有完成时”？','["如何看待改革开放进程中的“中国式奇迹”与“中国式难题”？","运用社会基本矛盾原理分析为什么“改革开放只有进行时、没有完成时”？"]','["“中国式奇迹”是改革开放解放和发展生产力的结果，“中国式难题”是发展起来以后出现的阶段性问题，二者都源于快速发展的进程。","看待奇迹与难题要坚持两点论，既充分肯定成就，又正视矛盾，通过深化改革破解难题。","生产关系必须适应生产力、上层建筑必须适应经济基础是社会发展的基本规律，改革是社会主义制度的自我完善和发展。","社会基本矛盾运动不会停止，随着实践发展会不断出现新情况新问题，因此改革开放只有进行时、没有完成时。"]','社会基本矛盾',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2014,36,'史纲','结合材料回答问题：
材料概述：材料1摘编邓小平1980年会见意大利记者法拉奇的谈话：天安门上的毛主席像要永远保留下去，毛主席最伟大的功绩是把马列主义原理同中国革命实际结合起来，功绩是第一位的、错误是第二位的；材料2介绍习近平总书记提出的改革开放前后两个历史时期“两个不能否定”的重要论述。
(1)1980年，邓小平为什么强调天安门上的毛主席像“永远要保留下去”？
(2)如何理解习近平总书记提出的“两个不能否定”的深刻内涵及其意义？','["1980年，邓小平为什么强调天安门上的毛主席像“永远要保留下去”？","如何理解习近平总书记提出的“两个不能否定”的深刻内涵及其意义？"]','["毛泽东是新中国的主要缔造者，毛泽东思想是党的宝贵精神财富，保留毛主席像体现了对党的历史和领袖功绩的尊重。","邓小平强调科学评价毛泽东和毛泽东思想，关系到党和国家的团结稳定与社会主义事业的前途。","“两个不能否定”指不能用改革开放后的历史时期否定改革开放前的历史时期，也不能用改革开放前的历史时期否定改革开放后的历史时期。","两个时期本质上都是党领导人民进行社会主义建设的实践探索，前者为后者提供了制度前提和经验准备。","正确看待党的历史，有利于坚定道路自信、维护党的执政基础，防止历史虚无主义。"]','十一届三中全会',0.5,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2014,37,'思修法基','结合材料回答问题：
材料概述：材料讲述2007年起27名大学毕业生放弃大城市优越生活、扎根海南鹦哥岭自然保护区从事生态保护的事迹：他们在艰苦条件下开展科研调查、帮助村民发展生产、守护热带雨林，被评价为“选择了一种有远见的生活方式”，引发社会对青年人生选择的讨论。
(1)为什么说鹦哥岭的大学生选择的是“一种有远见的生活方式”？
(2)怎样看待“理想很丰满，现实很骨感”这种说法？','["为什么说鹦哥岭的大学生选择的是“一种有远见的生活方式”？","怎样看待“理想很丰满，现实很骨感”这种说法？"]','["鹦哥岭大学生把个人理想融入国家和人民的事业，选择服务边远地区的生态保护，其价值远见超越了眼前物质利益。","有远见的生活方式在于追求人生的社会价值，在艰苦环境中磨炼成长，实现精神富足与长远发展。","理想与现实是对立统一的，理想源于现实又高于现实，实现理想必然要经历艰难曲折。","“理想很丰满，现实很骨感”看到了理想与现实的矛盾，但不能因现实困难而放弃理想，应在奋斗中把理想变为现实。"]','理想信念的作用',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2014,38,'形势与政策','结合材料回答问题：
材料概述：材料1摘编自托马斯·弗里德曼《世界是平的》相关报道：作者在印度班加罗尔考察后发现全球化使竞争场地被“铲平”，个人面临全球竞争，需要培养“学习如何学习”的能力；材料2讲述从“抢饭”到“抢饭碗”的变化，说明信息时代就业竞争已跨越国界。
(1)在“世界变平”的时代，为什么每个人“要培养 ‘学习如何学习’的能力”?
(2)从“抢饭”到“抢饭碗”的变化说明了什么？','["在“世界变平”的时代，为什么每个人“要培养 ‘学习如何学习’的能力”?","从“抢饭”到“抢饭碗”的变化说明了什么？"]','["信息化与全球化使知识更新加速，唯有掌握学习方法、具备持续学习能力，才能适应不断变化的竞争环境。","培养“学习如何学习”的能力是建设学习型社会和个人终身发展的必然要求。","从“抢饭”到“抢饭碗”表明全球化使就业竞争跨越国界，人才竞争成为国际竞争的核心。","这要求我国实施创新驱动发展战略和人才强国战略，提高劳动者素质，在国际竞争中赢得主动。"]','科教兴国与人才强国战略',1,1);
DELETE FROM real_subjective WHERE year=2015;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2015,34,'马原·哲学','结合材料回答问题：
材料概述：材料1介绍2014年首届世界互联网大会在乌镇召开，习近平总书记在贺词中指出互联网让国际社会越来越成为命运共同体，舆论认为互联网是“阿里巴巴的宝库”还是“潘多拉的魔盒”取决于命运共同体的共同治理；材料2讲述新兴互联网企业（“蚂蚁”）与传统企业（“大象”）竞争合作、融合发展的事例。
(1)联系自身实际，分析为什么"互联网到底是阿里巴巴的宝库，还是潘多拉的魔盒"取决于互联网的"命运共同体"？
(2)怎样以辩证的思维方式认识与处理"蚂蚁"与"大象"的关系？','["联系自身实际，分析为什么\"互联网到底是阿里巴巴的宝库，还是潘多拉的魔盒\"取决于互联网的\"命运共同体\"？","怎样以辩证的思维方式认识与处理\"蚂蚁\"与\"大象\"的关系？"]','["互联网的作用取决于使用它的人及其相互关系，网络空间是命运共同体，共建共治才能趋利避害。","矛盾具有两面性，互联网既可以是“宝库”也可能成“魔盒”，关键在于以正确的方式认识和运用它。","“蚂蚁”与“大象”即新兴互联网企业与传统企业是对立统一的关系，既相互竞争又相互依存、相互促进。","应以辩证思维看待竞争与合作，在斗争性中把握同一性，推动传统产业与新兴业态融合发展、共同升级。"]','对立统一规律',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2015,35,'毛中特','结合材料回答问题：
材料概述：材料以“让大猫小猫都有路走”为题，引述经济学家成思危讲的牛顿为大猫小猫分别开洞的寓言，说明市场需求多样，非公有制经济和中小企业在满足市场边角需求方面具有独特作用；材料还介绍了各种所有制经济依法平等使用生产要素、公平参与市场竞争的政策要求。
(1)现阶段我国发展社会主义市场经济为什么应坚持"让大猫小猫都有路走"？
(2)如何更好地发挥非公有制经济在经济发展中的作用？','["现阶段我国发展社会主义市场经济为什么应坚持\"让大猫小猫都有路走\"？","如何更好地发挥非公有制经济在经济发展中的作用？"]','["公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础。","“让大猫小猫都有路走”体现了坚持“两个毫不动摇”，使各种所有制经济依法平等使用生产要素、公平参与市场竞争。","非公有制经济在增长、就业、创新和税收等方面作用重大，激发其活力是发展社会主义市场经济的内在要求。","要完善产权保护制度，破除各种形式的市场壁垒，健全负面清单等制度，鼓励支持引导非公有制经济健康发展。"]','社会主义市场经济理论',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2015,36,'史纲','结合材料回答问题：
1925年郭沫若在一篇文章中讲述了这样一个故事：
十月十五日丁祭过后的第二天，孔子和他的得意门生颜回、子路、子贡三位在上海的文庙里吃着冷肉的时候，有四位年轻的大班抬了一乘朱红漆的四轿，一直闯进庙来，里面走出一位脸如螃蟹，胡须满腮的西洋人来，原来这位胡子螃蟹脸就是马克思。
孔子一见来的是马克思，他便禁不得惊喜着叫出：啊啊，有朋自远方来，不亦乐乎呀！你来到敝庙来，有什么见教呢？
马克思说：我是特为领教而来，我们的主义已经传到你们中国，我希望在你们中国能够实现，但是近来有些人说，我的主义和你的思想不同，所以在你的思想普遍着的中国，我的主义是没有实现的可能性，因此我便来直接领教你：究竟你的思想是怎么样？和我的主义怎样不同？
孔子说：难得你今天亲自到了我这里来，太匆促了，不好请你演讲，至少请你作一番谈话罢。你的理想的世界是怎样的呢？
马克思说：我的理想的世界，是我们生存在这里面，万人要能和一人一样自由平等地发展他们的才能，人人都各能尽力做事而不望报酬，人人都各能得生活的保障而无饥寒的忧虑，这就是我所谓"各尽所能，各取所需"的共产社会。
孔子说：你这个理想社会和我的大同世界竟是不谋而合，你请让我背一段我的旧文章给你听罢。"大道之行也，天下为公，选贤与能，讲信修睦；故人不独亲其亲，不独子其子，使老有所终，壮有所用，幼有所长，矜寡孤独废疾者皆有所养，男有分，女有归；货恶其弃于地也不必藏于己；力恶其不出于身也不必为己；是故谋闭而不兴，盗窃乱贼而不作，故外户而不闭，是谓大同"，这不是和你的理想完全一致的吗？
马克思说我的理想和有些空想家不同，我的理想不是虚构出来的，也并不是一步可以跳到的。我们先从历史上证明社会的产业有逐渐增值之可能，其次是逐渐增值的财产逐渐集中于少数人之手中，于是使社会生出贫乏病来，社会上的争斗便永无宁日。
孔子说：我从前也早就说过"不患寡而患不均，不患贫而患不安"的呀！
孔子的话还没有十分钟落脚，马克思早反对起来了：不对，不对！你和我的见解终竟是两样，我是患寡且患不均，患贫且患不安的，你要晓得，寡了便不均起来，贫了便是不安的根本。所以我对于私产的集中虽是反对，对于产业的增值却不惟不敢反对，而且还极力提倡，所以我们一方面用莫大的力量去剥夺私人的财产，而同时也要以莫大的力量来增值社会的产业。
孔子说：尊重物质本是我们中国的传统思想，洪范八政食货为先，管子也说过"仓源实而知礼节，衣食足而知荣辱"，我的思想乃至我国的传统思想，根本和你一样，总要先把产业提高起来，然后才来均分。
马克思到此才感叹起来：我不想在两千年前，在遥远的东方，已经有了你这样的一个老同志！你我的见解完全一致的，怎么有人曾说我的思想和你的不合，和你们中国的国情不合，不能施行于中国呢？
(1)"马克思进文庙"的历史背景是什么？
(2)如何理解孔子与马克思对话中谈到的他们之间思想上的"不同"与"一致"？','["\"马克思进文庙\"的历史背景是什么？","如何理解孔子与马克思对话中谈到的他们之间思想上的\"不同\"与\"一致\"？"]','["“马克思进文庙”写于1925年，此时马克思主义在中国广泛传播，中国思想界正围绕马克思主义与中国传统文化的关系展开激烈讨论。","五四运动后中国先进分子选择了马克思主义，如何对待以孔子为代表的传统文化成为时代课题。","孔子与马克思的“一致”在于都关怀人民生计、追求大同理想社会。","二者的“不同”在于阶级立场和实现路径：孔子的学说服务于宗法等级秩序，马克思主义立足唯物史观和阶级斗争，为无产阶级解放指明现实道路。","这表明马克思主义中国化内在地包含着与中国优秀传统文化相结合的要求。"]','马克思主义的创立与发展',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2015,37,'思修法基','结合材料回答问题：
材料概述：材料1介绍党的十八届四中全会首次专题讨论依法治国问题，网民热议“法治不仅是宏大的，也是具体的；它关乎国家治理，更关乎百姓福祉”，并引《韩非子》“奉法者强则国强”名言；材料2摘编全会决定关于党的领导和社会主义法治关系的论述。
(1)如何理解"法治关乎国家治理，更关乎百姓福祉"？
(2)为什么"全面推进依法治国，必须坚持党的领导"','["如何理解\"法治关乎国家治理，更关乎百姓福祉\"？","为什么\"全面推进依法治国，必须坚持党的领导\""]','["法治是国家治理体系和治理能力的重要依托，也是保障公民权利、维护公平正义的根本方式，直接关系百姓切身利益。","科学立法、严格执法、公正司法、全民守法使人民群众在每一个法律案件中感受到公平正义，增进民生福祉。","党的领导是社会主义法治最根本的保证，全面依法治国是党领导人民治理国家的基本方略。","党的领导与社会主义法治是一致的，党既领导立法、保证执法、支持司法、带头守法，又必须在宪法法律范围内活动。"]','全面依法治国',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2015,38,'形势与政策','结合材料回答问题：
材料概述：材料1记述1960年毛泽东与英国元帅蒙哥马利关于“50年以后中国的命运”的对话：蒙哥马利担心国家强大就倾向侵略，毛泽东回答中国不会向外侵略扩张；材料2介绍习近平2014年访欧时的阐述——“中国这头狮子已经醒了，但这是一只和平的、可亲的、文明的狮子”。
(1)毛泽东和蒙哥马利的"对话"反映了什么？
(2)如何理解习近平所说"中国这头狮子已经醒了，但这是一只和平的、可亲的、文明的狮子"？','["毛泽东和蒙哥马利的\"对话\"反映了什么？","如何理解习近平所说\"中国这头狮子已经醒了，但这是一只和平的、可亲的、文明的狮子\"？"]','["毛泽东与蒙哥马利的对话反映出西方对中国发展壮大的疑虑以及“国强必霸”的思维定式。","毛泽东的回答表明中国坚持和平立场，不搞侵略扩张，这一传统一脉相承。","“和平的、可亲的、文明的狮子”表明中国虽然发展壮大，但走的是和平发展道路，奉行互利共赢的开放战略。","中国的发展是世界和平力量的增长，中国梦与各国人民的美好梦想相通，中国永远不称霸、不搞扩张。"]','中国特色大国外交与百年变局',1,1);
DELETE FROM real_subjective WHERE year=2016;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2016,34,'马原·哲学','结合材料回答问题：
材料概述：材料摘编习近平总书记关于“四个全面”战略布局的论述：“四个全面”是从我国发展现实需要、人民群众热切期待和推动解决突出矛盾问题中得出来的，辩证唯物主义是中国共产党的世界观和方法论；评论指出“四个全面”的提出和协调推进是一个不断深化的过程。
(1)从认识的本质及其发展规律的视角，分析为什么说"''四个全面''是一个过程"？
(2)"四个全面"重要战略思想体现了怎样的辩证思维？','["从认识的本质及其发展规律的视角，分析为什么说\"''四个全面''是一个过程\"？","\"四个全面\"重要战略思想体现了怎样的辩证思维？"]','["认识的本质是主体在实践基础上对客体的能动反映，认识运动是实践、认识、再实践、再认识的无限发展过程。","“四个全面”的提出和形成源于治国理政的实践，并随实践发展不断丰富完善，其协调推进也需要在实践中逐步实现，故是一个过程。","真理是具体的、发展的，主观与客观、认识与实践的统一是历史的具体的统一。","“四个全面”体现了普遍联系和系统性的辩证思维，四者相互贯通、相互促进，构成有机统一的战略布局。","它坚持了两点论与重点论的统一，既全面部署又突出战略重点，体现了矛盾分析方法。"]','认识的反复性与无限性',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2016,35,'毛中特','结合材料回答问题：
材料概述：材料讲述新环保法实施后L市因污染被环保部约谈，“铁腕治污”使空气质量指标大幅下降，但部分缺乏环评手续的企业停产整顿后，工人失业、经济下行压力显现，由此引发关于经济发展与环境治理关系的广泛讨论。
(1)从"铁腕治污"引发广泛讨论看，我们应如何认识经济发展同环境治理的关系？
(2)"铁腕治污"及其引发的讨论对于推进我国生态文明制度建设有何启示？','["从\"铁腕治污\"引发广泛讨论看，我们应如何认识经济发展同环境治理的关系？","\"铁腕治污\"及其引发的讨论对于推进我国生态文明制度建设有何启示？"]','["经济发展与环境治理是辩证统一的，绿水青山就是金山银山，保护环境就是保护生产力、改善环境就是发展生产力。","以牺牲环境换取一时增长不可持续，环境治理可以倒逼产业转型升级，实现经济发展与环境改善的双赢。","“铁腕治污”表明必须实行最严格的环境保护制度，用制度和法治保护生态环境。","启示是健全生态环境责任追究、损害赔偿和考核评价等制度，把生态文明建设纳入制度化、法治化轨道，同时兼顾民生统筹推进治理。"]','美丽中国与绿色发展',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2016,36,'史纲','结合材料回答问题：
材料1
1944正值李自成领导的农民起义军进入北京推翻明王朝300周年，郭沫若毅然放下正在进行的先秦思想史研究，撰写《甲申三百年祭》，在这篇文章中，郭沫若深刻总结了李自成农民起义成功建立起大顺朝但旋即失败的历史教训，从3月19日起，这篇长文在重庆《新华日报》全文连载，文章发表后，引起社会各界的广泛关注，仅隔20天，毛泽东就在《学习和时局》报告中指出："我党历史上，曾有过几次表现了大的骄傲，都是吃了亏的……近日我们印了郭沫若论李自成的文章，也是叫同志们引为鉴戒，不要重犯胜利时骄傲的错误。"11月21日，毛曾东复信郭沫若："你的甲申三百年祭，我们把它当作整风文件看待，小胜既骄傲，一次又一次吃亏，如何避免此种毛病，实在值得注意。"
摘编自《（甲申三百年祭）风雨六十年》人民出版社2005年版
材料2
1949年3月23日，毛泽东率中公中央机关离开西柏坡前往北平（北京)，临行前，他对周围的人说:"同志们，我们就要进北平了，我们进北平，可不是李自成进北平，他们进了北平就变了，我们共产党人进北平，是要继续革命，建设社会主义，直到实现共产主义。"他兴奋地对周恩来说："今天是进京''赶考''嘛。"周恩来说："我们应当都能考试及格，不要退回来。"毛泽东说："退回去就失败了。我们决不当李自成，我们都希望考个好成绩。"
摘编自金冲及主编：《毛泽东传（1893-1949)》中央文献出版社1993年版
材料3
2013年7月11日至12日，习近平总书记来到革命圣地西柏坡，在同县乡村干部和群众座谈中指出，当年党中央离开西柏坡时，毛泽东同志说是进京赶考，六十多年过去了，我们取得了巨大进步，中国人民站起来了，富起来了，但我们面临的挑战和问题依然严峻复杂，应该说党面临的''赶考''远未结束，我们党要带领人民实现全面建成小康奋斗目标，不断坚持和发展中国特色社会主义，就是这场考试的继续。所有领导干部和全体党员要继续把人民对我们党的''考试''、把我们党正在经受和将要经受各种考验的''考试''考好，努力交出优异的答卷。"
摘编自《习近平关于实现中华民族伟大复兴的中国梦论述摘编》
中央文献出版社2013年版
(1)1949年春，为什么毛泽东把离开西柏坡前往北平比作"赶考"
(2)如何理解习近平所说的"党面临的''赶考''远未结束','["1949年春，为什么毛泽东把离开西柏坡前往北平比作\"赶考\"","如何理解习近平所说的\"党面临的''赶考''远未结束"]','["“赶考”比喻党执政面临的新考验，毛泽东以此告诫全党在胜利面前保持谦虚谨慎、不骄不躁、艰苦奋斗的作风，防止重蹈李自成失败的覆辙。","由革命党转变为执政党，能否经受住执政的考验、跳出历史周期率，是当时党面临的重大课题。","习近平强调“赶考”远未结束，是因为党在长期执政条件下仍面临执政考验、改革开放考验、市场经济考验、外部环境考验。","实现民族复兴的历史使命尚未完成，党必须继续保持“赶考”的清醒，全面从严治党，向人民交出新的合格答卷。"]','全面从严治党',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2016,37,'思修法基','结合材料回答问题：
材料概述：材料列举中华民族重家风家教的传统事例：司马光以《训俭示康》教育儿子以俭素为美，郑板桥教子重品行，以及当代“最美家庭”传承好家风的故事，说明好家风的传承也是延续优良文明基因、培育社会主义核心价值观的过程。
(1)为什么说"好家风的传承过程，同样也是延续优良文明基因的过程"？
(2)如何通过好家风的传承弘扬社会主义核心价值观？','["为什么说\"好家风的传承过程，同样也是延续优良文明基因的过程\"？","如何通过好家风的传承弘扬社会主义核心价值观？"]','["家风是家庭成员道德养成的起点，好家风承载着中华民族孝老爱亲、勤俭诚信等传统美德，其传承延续了优良的文明基因。","家庭是社会的细胞，家风通过代际传递把道德规范内化为家庭成员的行为习惯，进而影响社风民风。","社会主义核心价值观与优良家风在价值内核上相通，好家风是核心价值观在家庭中的具体体现。","通过家庭教育、长辈示范和家规家训的传承弘扬好家风，能使核心价值观落细落小落实，在潜移默化中培育践行。"]','社会主义核心价值观',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2016,38,'形势与政策','结合材料回答问题：
材料概述：材料1摘自习近平在纪念中国人民抗日战争暨世界反法西斯战争胜利70周年大会上的讲话，强调中国人民为世界反法西斯战争胜利作出重大贡献，要共同维护以联合国宪章宗旨和原则为核心的国际秩序和国际体系；材料2介绍习近平在联合国系列峰会上阐述打造人类命运共同体的主张。
(1)分析当今世界各国"共同维护以联合国宪章宗旨和原则为核心的国际秩序和国际体系"的重要性所在。
(2)如何理解"打造人类命运共同体"的主张"继承了联合国宪章精神，符合国际社会的普遍需要"？','["分析当今世界各国\"共同维护以联合国宪章宗旨和原则为核心的国际秩序和国际体系\"的重要性所在。","如何理解\"打造人类命运共同体\"的主张\"继承了联合国宪章精神，符合国际社会的普遍需要\"？"]','["以联合国宪章宗旨和原则为核心的国际秩序是战后世界和平与发展的基石，维护它符合各国共同利益。","当前单边主义、强权政治和各种全球性挑战交织，更需要各国共同维护多边主义和国际关系基本准则。","打造人类命运共同体主张建立平等相待、合作共赢的伙伴关系，营造公道正义、共建共享的安全格局。","这一主张继承和弘扬了联合国宪章关于主权平等、和平解决争端等精神，回应了国际社会求和平、谋发展、促合作的普遍需要。"]','人类命运共同体',1,1);
DELETE FROM real_subjective WHERE year=2017;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2017,34,'马原·哲学','结合材料回答问题：
2008年，斯坦福大学的计算机科学家设计出了第一个专家系统：1982年，加州理工学院物理学家提出了新的神经网络模型;1997年，IBM“深蓝”电脑线路国际教程世界观军卡斯帕罗夫;2011年，IBM超级计算机“沃森”在美国电视答题节目中战胜两种人类冠军;2013年，机器在人脸识别上超过人类;仅一年后，机器人在物体识别上也战胜……未来人工智能继续超越人类的可能性很高。
在人工智能应用前景充满无限可能的情况下，其潜在风险也引发了广泛讨论。2016年2月，在美国加州发生了一起死人驾驶汽车因躲避路上障碍物而撞上公交车的交通事故。这凸显出人中智能设备在应对人类社会各种场景时面临的挑战，人们还担心人工智能技术成熟后的问题，比如将机器人用于战争是否会带来像核武器一样的后果。
有学者表示，人机对弈是人类思考自身作用契机。人工智能的目的是帮助人类，创造出比李世石更优秀的棋手应该是人类的胜利，也有学者认为，在面对复杂的伦理问题时，人工智能技术可能会陷入不可预知的选择困境，著名物理学家霍金也发出警告;“我不认为人工智能的进步一定会是良性的。”
德国人工智能研究所柏林分析所长汉斯·乌斯克莱特强调说，人工智能的研究方向不是要取代人类，而是要与人类互补，增强人类的能力，人工智能不会取代人类，因为只有人类才具有创造力和目标，而机器只关注如何解决眼前遇到的问题。要让人工智能避免犯下道德层面的错误，关键在于人类自己，在美国《连线》杂志创始主编凯文·凯利看来，每个发明都不可避免带来新问题，但同时也会带来新的解决方案，解决这些问题的方式不是减少技术的使用，而是通过改进技术来提供解决方案，他认为，即使新的技术发展带来的49%是问题，但它首先带来了51%的好处，这正是人类进步的动力。
从这个意义上讲，“阿尔法围棋”和李世石无论谁胜谁败，人类都是最后的赢家，总之，用好人工智能，关键还在人类自身。
(1)从真理和价值辩证关系看，为何人们会对人工智能技术产生多种多样的看法与评价?
(2)如何理解“用好人工智能，关键还在人类自身”?','["从真理和价值辩证关系看，为何人们会对人工智能技术产生多种多样的看法与评价?","如何理解“用好人工智能，关键还在人类自身”?"]','["真理尺度与价值尺度是实践活动的两个基本尺度，人们既依据对人工智能的客观认识，又依据各自的需要和利益进行评价。","价值评价具有主体性，不同主体的立场、需要和知识背景不同，因而对同一技术产生多种多样的看法。","科学技术本身是中性的，其社会作用取决于人如何认识和运用，人是实践活动的主体。","用好人工智能要求坚持真理尺度与价值尺度的统一，在发展技术的同时以正确价值观引导其造福人类。"]','真理与价值',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2017,35,'毛中特','结合材料回答问题：
材料概述：材料介绍福建宁德赤溪村和下党乡东溪村的脱贫历程：在当地党委政府推动下，通过移民搬迁“挪穷窝”、转变观念、因地制宜发展生态旅游和特色种植等产业实现脱贫致富；材料还引述习近平总书记关于农村贫困人口脱贫是全面建成小康社会最突出短板、实施精准扶贫的论述。
(1)如何理解农村人口脱贫是我国全面建设小康社会“最突出的短板”?
(2)东溪村脱贫致富之路对我国实施精准扶贫、打赢脱贫攻坚战有何启示?','["如何理解农村人口脱贫是我国全面建设小康社会“最突出的短板”?","东溪村脱贫致富之路对我国实施精准扶贫、打赢脱贫攻坚战有何启示?"]','["全面建成小康社会的核心在“全面”，农村贫困人口脱贫直接关系小康社会的成色，是最艰巨的任务和最突出的短板。","我国发展不平衡，农村特别是贫困地区在收入、基础设施和公共服务方面与全国平均水平差距明显。","东溪村依托自身资源发展特色产业实现脱贫，表明扶贫必须精准施策、因地制宜。","启示是坚持开发式扶贫，把输血与造血结合起来，发挥基层组织和群众的内生动力，通过产业扶贫实现稳定脱贫。"]','共同富裕',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2017,36,'史纲','结合材料回答问题：
长征途中，我们党通过艰苦卓绝的实践探索，不断打开战局的最重要的保证。联系在一起，把长征的大方向同建立抗日前进阵地联系在一起。实现了国内革命战争的抗日民族战争的转变，为夺取中国人民抗日战争胜利，进而夺取新民主主义革命胜利打下了坚实基础。
长征的胜利，不仅保存了革命力量，而且使我们党找到了中国革命力量生存发展的落脚点，打到了中国革命事业胜利前进新的出发点，从长征的终点出发，我们党领导中国人民展开了中国革命波澜壮阔的新画卷。
历史是不断向前的、要达到理想的彼岸，就要沿着我们确定的道路不断前进，每一代人有每一代人的长征路，每一代人都要走好自己的长征路。今天，我们这一代人的长征，就是要实现“两个一百年”奋斗目标，实现中华民族伟大复兴的中国梦。
实现伟大的理想，没有平坦的大道可走，夺取坚持和发展中国特色社会主义伟大事业新发展，夺取推进党的建设新的伟大工程新成效，夺取具有许多新历史特点的伟大斗争新胜利，我们还有许多“雪山”、“草地”需要跨越，还有许多“娄山关”、“晴子口”需要征服，一切贫图安逸、不愿继续艰苦奋斗的想法都是要不得的，一切骄傲自满、不愿继续开拓前进的想法都是要不得的。
长征永远在路上。一个不记得来路的民族，是没有出路的民族。不论我们的事业发展到哪一步，不论我们取得了多大成就，我们都要大力弘扬伟大长征精神，在新的长征路上继续奋勇前进。
摘自习近平《在纪念红军长征胜利80周年大会上的讲话》
(1)长征的胜利既是“中国革命力量生存发展新的落脚点”也是“中国革命事业胜利前进的出发点”?
(2)如何理解“长征永远在路上”?','["长征的胜利既是“中国革命力量生存发展新的落脚点”也是“中国革命事业胜利前进的出发点”?","如何理解“长征永远在路上”?"]','["长征的胜利实现了红军的战略转移，保存了革命骨干力量，使中国革命转危为安，为革命力量的生存发展赢得了新的落脚点。","长征的胜利推动了革命形势的转变，陕北根据地成为抗日战争和中国革命胜利前进的出发点。","长征铸就的伟大长征精神是党和人民宝贵的精神财富。","“长征永远在路上”是指实现民族复兴是新的长征，仍需跨越新的“雪山”“草地”，必须继续弘扬长征精神、走好新时代的长征路。"]','遵义会议',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2017,37,'思修法基','结合材料回答问题：
2015年五一劳动节前夕，讲述了8个工匠“八双劳动的手”所缔造的“神话”，节目播出之后，很快引起社会热议，在不到十天的时间里，相关话题的微博阅读量就超过了3560万次，人们发现，走入镜头的工匠们，他们文化不同，年龄有别，但拥有一个共同的闪光点——立足于本职工作，敬业奉献，数十年如一日地追求者职业技能的极致化，靠着传承和钻研，凭着专注和坚守，创造了一个又一个“中国制造”的奇迹。在2016年“两会”上，国务院总理李克强在《政府工作报告》中提出要积极培育“工匠精神”，“工匠精神”第一次写入政府工作报告。
“工匠精神”是一种职业精神，工匠们对所从事的事业的爱心和忠心，令人高山仰卧=止，中国航天科技集团一院火箭总装厂高级技师高凤林，36年一直从事火箭的“心脏”——发动机焊接工作，以国为重、扎根一线，是发动机焊接第一人，面对很多企业试图高薪聘请不为所动，他说：“每每看到自己生产的发动机把卫星送到太空，就有一种成功后的自豪感，这种自豪感用金钱买不到。”这也代表了大国工匠们的心声。
“工匠精神”是一种工作态度，在工匠们的心目中，制作出来的产品没有最好，只有更好，高凤林在36年的工作中，攻克了200多项技术难关，经他的手焊接了140多火箭的发动机，焊接的焊缝总长度达到12万多米，没有出现过一次质量问题，他先后获得过部院科技进步一等奖、国家科技进步二等奖、2014年组伦敦国际发明展览会金等奖等30多种奖励，而这没有一丝不苟的工作态度显然是无法做到的。
随着时代的发展，工匠的工作或许会逐渐被机器所取代，但是“工匠精神”却不可能被代替，我国作为一个拥有“四大发明”的文明古国，具有历史悠久而技艺高超的手工业，薪火相传的能工匠们留下了数不胜数的传世佳作，我们今天弘扬“工匠精神”不仅是对传统工匠技艺的留念，而且是对一切职业的道德呼唤。“工匠精神”，不仅仅是制造业的需要，也不仅仅是企业家的需要，它代表一个时代的气质，是我们每一个人的事业追求与人生态度。
摘编《中国青年报》(2015年5月11日)、央视网(2016年4月22日、10月9日)等
(1)“工匠精神”的实质是什么?
(2)为什么说弘扬“工匠精神”是“对一切职业的道德呼唤”?','["“工匠精神”的实质是什么?","为什么说弘扬“工匠精神”是“对一切职业的道德呼唤”?"]','["工匠精神的实质是精益求精、专注执着、追求卓越的职业精神，体现着敬业奉献的职业道德。","它把对产品质量的极致追求内化为职业信念，是职业活动中知行合一的道德品质。","任何职业都承担着社会责任，都需要从业者爱岗敬业、诚实劳动，故弘扬工匠精神是对一切职业的道德呼唤。","弘扬工匠精神有利于提升产品和服务质量、建设制造强国，也有利于在全社会形成尊重劳动、崇尚精品的风尚。"]','社会公德、职业道德、家庭美德、个人品德',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2017,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍2016年二十国集团领导人杭州峰会：主题为“构建创新、活力、联动、包容的世界经济”，这是近年来中国主办的级别最高、影响最深远的国际峰会；习近平主席以“桥”比喻G20，表示愿同各方共同架设合作之桥、繁荣之桥、未来之桥，为世界经济把脉开方。
(1)结合当前国际环境，分析二十国集团领导人杭州峰会主题的现实意义。
(2)习近平主席用“桥”比喻二十国集团，体现出中国怎样的外交理念与世界情怀?','["结合当前国际环境，分析二十国集团领导人杭州峰会主题的现实意义。","习近平主席用“桥”比喻二十国集团，体现出中国怎样的外交理念与世界情怀?"]','["世界经济增长乏力、逆全球化思潮抬头，杭州峰会以“构建创新、活力、联动、包容的世界经济”为主题，为世界经济指明方向。","峰会推动G20从危机应对向长效治理机制转型，为完善全球经济治理贡献了中国方案。","“桥”的比喻体现中国倡导互联互通、合作共赢的外交理念，愿做世界和平的建设者、全球发展的贡献者。","它彰显了中国推动构建人类命运共同体、同各国共建共享美好未来的世界情怀。"]','中国特色大国外交与百年变局',1,1);
DELETE FROM real_subjective WHERE year=2018;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2018,34,'马原·哲学','结合材料回答问题：
材料概述：材料引述党的十九大前后媒体关于我国社会主要矛盾变化的讨论，指出改革开放以来我们党紧紧抓住社会主要矛盾，坚持以经济建设为中心，推动解决人民日益增长的需要同落后的社会生产之间的矛盾；进入新时代，社会主要矛盾转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，发展仍是解决我国一切问题的基础和关键。（原材料引自公开报道，此处为概述）
(1)如何理解“抓住了这个主要矛盾，一切问题就迎刃而解了”？
(2)根据矛盾主要方面在事物发展中的地位和作用原理，说明为什么“发展是解决我国一切问题的基础和关键”。','["如何理解“抓住了这个主要矛盾，一切问题就迎刃而解了”？","根据矛盾主要方面在事物发展中的地位和作用原理，说明为什么“发展是解决我国一切问题的基础和关键”。"]','["主要矛盾在矛盾体系中处于支配地位，对事物发展起决定作用，抓住主要矛盾就抓住了解决问题的关键，其他矛盾便易于解决。","我国社会主要矛盾已转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，抓住它就能统领各项工作。","矛盾的主要方面规定事物的性质，解决矛盾必须着重把握矛盾的主要方面。","不平衡不充分的发展是当前矛盾的主要方面，解决它根本上要靠发展，故发展是解决我国一切问题的基础和关键。","坚持两点论与重点论的统一，在集中力量推动发展的同时统筹兼顾其他方面。"]','主要矛盾与次要矛盾',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2018,35,'毛中特','结合材料回答问题：
材料概述：材料摘编党的十九大相关报道：经过长期努力，中国特色社会主义进入了新时代，我国社会主要矛盾发生转化；党的十九大把习近平新时代中国特色社会主义思想写入党章，确立为党必须长期坚持的指导思想，这是党的指导思想又一次与时俱进。
(1)如何理解"中国特色社会主义进入了新时代"？
(2)为什么说习近平新时代中国特色社会主义思想是马克思主义中国化最新成果？','["如何理解\"中国特色社会主义进入了新时代\"？","为什么说习近平新时代中国特色社会主义思想是马克思主义中国化最新成果？"]','["经过长期努力，我国发展站到新的历史起点上，社会主要矛盾发生转化，中国特色社会主义进入新时代，这是我国发展新的历史方位。","新时代意味着中华民族迎来了从站起来、富起来到强起来的伟大飞跃，科学社会主义在中国焕发出强大生机活力。","习近平新时代中国特色社会主义思想系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义的时代课题。","这一思想坚持马克思主义基本原理与新时代中国实际相结合，是对马列主义、毛泽东思想和中国特色社会主义理论体系的继承和发展，因而是马克思主义中国化最新成果。"]','中国特色社会主义进入新时代',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2018,36,'史纲','结合材料回答问题：
材料概述：材料1摘自《毛泽东选集》：从鸦片战争到五四运动前夜，中国人从西方学来的思想武器和政治方案都“抵不住”，屡试屡败；十月革命送来马克思列宁主义，中国共产党应运而生；材料2摘编建党96周年评论，讲述党从50多名党员发展为8900多万党员的大党，由“简”而“巨”，团结带领人民取得举世瞩目成就。
(1)为什么说中国共产党是"应运而生"？
(2)中国共产党为什么能由"简"而"巨"，团结带领人民取得举世瞩目的伟大成就？','["为什么说中国共产党是\"应运而生\"？","中国共产党为什么能由\"简\"而\"巨\"，团结带领人民取得举世瞩目的伟大成就？"]','["近代各种救国方案相继失败，工人阶级成长壮大，马克思列宁主义传入并与中国工人运动相结合，中国共产党应运而生，是近代中国社会矛盾发展和人民斗争的必然产物。","党的成立顺应了时代要求和人民愿望，使中国革命有了主心骨。","党能由“简”而“巨”，根本在于始终坚守初心使命，把马克思主义与中国实际相结合，找到正确的革命和建设道路。","党紧紧依靠人民、为人民谋幸福，获得最广泛的支持，并勇于自我革命、保持先进性纯洁性，因而能团结带领人民取得伟大成就。"]','中国共产党的成立',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2018,37,'思修法基','结合材料回答问题：
材料概述：材料1讲述“中国核潜艇之父”黄旭华的事迹：他少年时目睹日军轰炸下的山河破碎，立志科学救国，此后隐姓埋名三十年为祖国研制核潜艇；材料2讲述科学家黄大年放弃国外优越条件归国，秉承“祖国的需要就是最高需要”的人生信条，带领团队填补多项国内技术空白，为科技强国梦奋斗到生命最后一刻；两人的一生都体现了对理想信念的不懈追求。（原材料为公开媒体报道摘编，此处为原创概述）
(1)、为什么说青年时期确立正确的理想信念能够为人的一生提供“无穷的力量”？
(2)青年如何在实现中国梦的实践中放飞自己的青春梦想？','["、为什么说青年时期确立正确的理想信念能够为人的一生提供“无穷的力量”？","青年如何在实现中国梦的实践中放飞自己的青春梦想？"]','["理想信念是人生的精神支柱和前进动力，为人生提供方向指引和强大意志支撑。","青年时期确立正确的理想信念，能够为一生的奋斗确立目标、提供不竭动力，黄旭华、黄大年正是靠理想信念成就报国事业。","理想信念激励人在困难与挫折面前坚韧不拔，把个人有限的力量汇入伟大事业而变得“无穷”。","青年应把个人梦融入中国梦，把理想落实到勤学、修德、明辨、笃实的行动中，在服务国家和人民的实践中放飞青春梦想。"]','理想信念的作用',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2018,38,'形势与政策','结合材料回答问题：
材料概述：材料1介绍2008年国际金融危机以来世界经济增长动能不足、贫富分化加剧、非传统安全威胁蔓延的背景，一些人把世界乱象归咎于经济全球化，民粹主义、孤立主义和贸易保护主义等逆全球化思潮涌动；材料2引述国际人士评价，认为“一带一路”倡议是应对全球性挑战的中国方案，有助于推动经济全球化更加平衡、包容、和谐发展。（原材料为公开报道/著作摘编，此处为原创概述）
(1)为何要引导经济全球化释放出更多“正面效应”？
(2)如何理解“‘一带一路’不是中国一家的独奏，而是沿线国家的合唱”？','["为何要引导经济全球化释放出更多“正面效应”？","如何理解“‘一带一路’不是中国一家的独奏，而是沿线国家的合唱”？"]','["经济全球化是社会生产力发展的客观要求和科技进步的必然结果，为世界经济增长提供了强劲动力。","全球化也带来发展失衡、贫富分化等问题，简单归咎于全球化并退回保护主义没有出路。","引导全球化释放正面效应，才能实现共赢共享、让不同国家和群体共享发展成果。","“一带一路”坚持共商共建共享原则，向所有志同道合的国家开放，各参与国平等协商、优势互补、成果共享，故是“合唱”而非“独奏”。"]','高质量共建一带一路',1,1);
DELETE FROM real_subjective WHERE year=2019;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2019,34,'马原·哲学','结合材料回答问题：
材料概述：材料1回顾1978年《实践是检验真理的唯一标准》一文引发的全国大讨论，冲破“两个凡是”的思想禁锢，为改革开放作了思想准备；材料2摘自党的十九大报告，强调实践没有止境，理论创新也没有止境。
(1)如何理解“实践是检验真理的唯一标准”?
(2)从实践标准的绝对性与相对性的关系，谈谈你对“实践没有止境，理论创新也没有止境”的认识。','["如何理解“实践是检验真理的唯一标准”?","从实践标准的绝对性与相对性的关系，谈谈你对“实践没有止境，理论创新也没有止境”的认识。"]','["实践是主观见之于客观的活动，具有直接现实性，只有实践能把主观认识与客观实际联系起来加以对照，因而是检验真理的唯一标准。","真理的本性是主观与客观相符合，这一检验只能由实践来完成。","实践标准是绝对性与相对性的统一：实践最终能够检验一切认识，但一定历史阶段的实践对真理的检验又是有限的、有待发展的。","实践不断发展，对理论的检验和丰富也随之深化，因此实践没有止境，理论创新也没有止境。"]','实践是认识的基础',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2019,35,'毛中特','结合材料回答问题：
材料概述：材料1讲述深圳经济特区的故事：从两条小巷、一条小街的小渔村发展为现代化国际化大都市，创造了世界工业化、城市化、现代化史上的奇迹；材料2摘编庆祝改革开放40周年相关报道，引述习近平总书记“以改革开放的眼光看待改革开放”的要求。
(1)为什么说“改革开放是决定当代中国命运的关键抉择”?
(2)如何理解进入新时代必须“以改革开放的眼光看待改革开放”?','["为什么说“改革开放是决定当代中国命运的关键抉择”?","如何理解进入新时代必须“以改革开放的眼光看待改革开放”?"]','["改革开放极大改变了中国的面貌，使中国大踏步赶上时代，实现了从温饱不足到迈向全面小康的飞跃，因而是决定当代中国命运的关键抉择。","改革开放是党和人民事业大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路。","以改革开放的眼光看待改革开放，就是要把握其历史逻辑与时代要求，在新时代把改革开放进行到底。","面对新矛盾新挑战，必须以更大的政治勇气深化改革、扩大开放，用改革开放的办法解决发展中的问题。"]','改革开放的历史进程',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2019,36,'史纲','结合材料回答问题：
材料1.
马克思主义不仅深刻改变了世界，也深刻改变了中国，中华民族在几千年的历史进程中创造了灿烂的中华文明，为人类文明进步作出了重大贡献。1840年鸦片战争以后，西方列强凭着坚船利炮野蛮轰开了中国的大门，中华民族陷入内忧外患的悲惨境地.
近代以后，争取名族独立、人民解放和实验国家富强，人民幸福就成为中国人民的历史任务。在旧式的农民战争走到尽头，不触动封建根本的自强运动和改良主义屡屡碰壁，资产阶级革命派领导的革命和西方资本主义的其它种种方案纷纷破产的情况下，十月革命一声炮响，为中国送来了马克思列宁主义，给苦苦探寻救亡图存出路的中国人民指明了前进方向，提供了全新选择。
中国共产党诞生后，中国共产党人把马克思列宁主义基本原理同中国革命和建设具体实际结合起来，团结带领人民经过长期奋斗，完成新民主主义革命和社会主义革命，建立起中华人民共和国和社会主义基本制度，进行了社会主义的艰辛探索，实现了中华民族从东亚病夫到站起来的伟大飞跃。
改革开放以来，中国共产党人把马克思列宁主义基本原理同中国改革开放的具体实际结合起来，团结带领人民进行建设中国特色社会主义新的伟大实践，使中国大踏步赶上了时代，实现了中华民族从站起来到富起来的伟大飞跃。
材料2.
经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位。
中国特色社会主义进入新时代，意味着近代以来久经磨难的中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了实现中华民族伟大复兴的光明前景，意味着科学社会主义在二十一世纪的中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜，意味着中国特色社会主义道路、理论、制度、文化不断发展，拓展了发展中国家走向现代化的途径，给世界上那些希望加快发展又希望保持自身独立性的国家和民族提供了全新选择，为解决人类问题贡献了中国智慧和中国方案。
摘自 习近平《决胜全面建成小康社会度夺取新时代中国特色社会主义伟大胜利——在中国共产党第十九次全国代表大会上的报告》
(1)如何理解马克思列宁主义给中国人民“指明了前进方向，提供了全新选择”?
(2)中华民族实现了从东亚病夫到站起来，从站起来到富起来的伟大飞跃，并迎来了从富起来到强起来的伟大飞跃说明了什么?','["如何理解马克思列宁主义给中国人民“指明了前进方向，提供了全新选择”?","中华民族实现了从东亚病夫到站起来，从站起来到富起来的伟大飞跃，并迎来了从富起来到强起来的伟大飞跃说明了什么?"]','["十月革命后，马克思列宁主义给正在苦闷中探索的中国人民指明了争取民族独立和人民解放的科学道路。","它使中国先进分子找到了观察国家命运的思想武器，促成中国共产党诞生，从而提供了不同于旧民主主义的全新选择。","从东亚病夫到站起来、富起来再到强起来的飞跃，证明只有社会主义才能救中国，只有中国特色社会主义才能发展中国。","这一历程说明党的领导、马克思主义的指导与中国实际相结合是民族复兴的根本保证。"]','五四运动',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2019,37,'思修法基','结合材料回答问题：
材料概述：材料介绍我国第五个烈士纪念日向人民英雄纪念碑敬献花篮的仪式，讲述纪念碑浮雕镌刻的英雄史诗和习近平总书记崇尚英雄、缅怀先烈的论述；材料还介绍《中华人民共和国英雄烈士保护法》的施行及依法惩治亵渎英烈行为的案例。
(1)如何理解“英雄烈士的事迹和精神是中华民族共同的记忆和宝贵的精神财富”?
(2)从法律社会作用的角度，分析为什么要用法律的名义保护英雄烈士?','["如何理解“英雄烈士的事迹和精神是中华民族共同的记忆和宝贵的精神财富”?","从法律社会作用的角度，分析为什么要用法律的名义保护英雄烈士?"]','["英雄烈士为民族独立和人民幸福献身，其事迹和精神凝结着中华民族共同的历史记忆和价值追求，是宝贵的精神财富。","崇尚英雄、缅怀先烈有利于弘扬爱国主义精神、凝聚民族力量。","法律具有指引、评价、教育等社会作用，用法律保护英雄烈士体现了国家的价值导向。","英雄烈士保护法通过制裁亵渎英烈的行为，维护社会公共利益和民族共同记忆，引导全社会尊崇英雄、捍卫正义。"]','法治思维与法律权利义务',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2019,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍2018年中国四大主场外交活动——博鳌亚洲论坛年会、上合组织青岛峰会、中非合作论坛北京峰会、首届中国国际进口博览会：习近平主席在系列主旨演讲中深入阐述构建人类命运共同体思想，主场外交成为全新的“中国名片”，为世界发展提供了中国智慧和中国方案。
(1)为什么说主场外交已成为全新的 “中国名片”?
(2)中国主场外交贯穿着怎么样的外交关系理念?中国为世界发展提供了哪些智慧和方案?','["为什么说主场外交已成为全新的 “中国名片”?","中国主场外交贯穿着怎么样的外交关系理念?中国为世界发展提供了哪些智慧和方案?"]','["中国依托进博会、上合峰会等主场外交平台，向世界展示开放合作形象，主场外交成为全新的“中国名片”。","主场外交贯穿着和平、发展、合作、共赢的理念，倡导相互尊重、公平正义、合作共赢的新型国际关系。","中国提出构建人类命运共同体、共建“一带一路”等主张，为全球治理提供了中国智慧和中国方案。","扩大开放、进口博览会等举措表明中国以自身发展为世界提供机遇，推动建设开放型世界经济。"]','中国特色大国外交与百年变局',1,1);
DELETE FROM real_subjective WHERE year=2020;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2020,34,'马原·哲学','结合材料回答问题：
材料概述：材料讲述自然界食物链中“一物降一物”的生态平衡现象，并结合科研人员突破传统思维、利用生物天敌防治虫害实现绿色治理的事例，说明创新思维的重要性。（公开文字版真题未附完整材料，此处为概述）
(1)分析自然界中的“一物降一物”平衡法则所体现的唯物辩证法原理。
(2)为什么说“跳出传统思维模式，创新之路会越走越宽”？','["分析自然界中的“一物降一物”平衡法则所体现的唯物辩证法原理。","为什么说“跳出传统思维模式，创新之路会越走越宽”？"]','["“一物降一物”体现了事物普遍联系和矛盾对立统一的原理，生物之间相互依存、相互制约，维系着生态系统的动态平衡。","矛盾的同一性与斗争性相互联结，生物链中的制约关系正是同一性与斗争性共同作用的表现。","利用天敌治虫表明人可以认识和利用客观规律，在尊重规律的基础上发挥主观能动性。","实践是认识发展的动力，突破传统思维定式、根据实践需要创新方法，认识和实践之路就会越走越宽。"]','对立统一规律',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2020,35,'毛中特','结合材料回答问题：
材料概述：材料围绕党的十九届四中全会《中共中央关于坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化若干重大问题的决定》，介绍中国特色社会主义制度的显著优势与国家治理现代化的部署。（公开文字版真题未附完整材料，此处为概述）
(1)如何理解“中国特色社会主义制度”是党和人民在长期实践探索中形成的科学制度体系？
(2)阐述坚持和完善中国特色社会主义制度与推进国家治理体系和治理能力现代化之间的关系。','["如何理解“中国特色社会主义制度”是党和人民在长期实践探索中形成的科学制度体系？","阐述坚持和完善中国特色社会主义制度与推进国家治理体系和治理能力现代化之间的关系。"]','["中国特色社会主义制度是党和人民把马克思主义基本原理同中国具体实际相结合、在长期实践探索中逐步建立和完善的，具有深厚的实践基础和历史逻辑。","这一制度体系以根本制度、基本制度、重要制度为支撑，各领域制度相互衔接，具有显著优势，因而是科学制度体系。","中国特色社会主义制度是国家治理体系和治理能力的根本依托，国家治理体系和治理能力是制度及其执行能力的集中体现。","坚持和完善制度为治理现代化提供根本遵循，推进治理现代化又使制度优势更好转化为治理效能，二者相辅相成、有机统一。"]','全面深化改革总目标',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2020,36,'史纲','结合材料回答问题：
材料概述：材料回顾1949年3月中共中央进驻北京香山后，指挥渡江战役、筹备新政协、缔造中华人民共和国的历史，以及“进京赶考”的告诫。（公开文字版真题未附完整材料，此处为概述）
(1)如何理解中共中央在香山虽然只有半年时间，但在中国共产党历史及中华人民共和国历史上具有非常重要的地位？
(2)为什么说中华人民共和国的成立彻底改变了近代以后100多年中国积贫积弱、任人欺凌的悲惨命运？','["如何理解中共中央在香山虽然只有半年时间，但在中国共产党历史及中华人民共和国历史上具有非常重要的地位？","为什么说中华人民共和国的成立彻底改变了近代以后100多年中国积贫积弱、任人欺凌的悲惨命运？"]','["中共中央在香山期间指挥了渡江战役等解放全中国的决定性战役，筹备召开新政协、缔造了中华人民共和国。","香山时期完成了中国革命从夺取全国胜利到建立新中国的历史转折，谋划了新中国的制度框架和建国蓝图，故地位极为重要。","中华人民共和国的成立结束了帝国主义奴役中国人民的历史，实现了民族独立和人民解放。","新中国的成立使中国人民站起来、成为国家和社会的主人，为国家富强和民族复兴开辟了广阔道路，彻底改变了近代以来积贫积弱、任人欺凌的命运。"]','中华人民共和国成立的意义',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2020,37,'思修法基','结合材料回答问题：
材料概述：材料讲述“共和国勋章”获得者张富清深藏功名60余年、在平凡岗位上默默奉献的事迹，以及国家首次集中颁授国家勋章和国家荣誉称号的情况。（公开文字版真题未附完整材料，此处为概述）
(1)结合张富清高尚的人生追求，说明理想信念的力量。
(2)国家颁授国家勋章和国家荣誉称号，对全社会弘扬和践行社会主义核心价值观有何重要意义？','["结合张富清高尚的人生追求，说明理想信念的力量。","国家颁授国家勋章和国家荣誉称号，对全社会弘扬和践行社会主义核心价值观有何重要意义？"]','["理想信念是人生的精神之钙，为人的行为提供方向指引和精神动力。","张富清深藏功名、在平凡岗位默默奉献，正是坚定理想信念支撑他淡泊名利、坚守初心，体现了理想信念的强大力量。","国家勋章和国家荣誉称号树立了践行社会主义核心价值观的时代标杆，发挥了先进典型的示范引领作用。","以国家最高礼遇礼敬英雄模范，有利于在全社会形成崇尚英雄、见贤思齐的风尚，推动核心价值观内化于心、外化于行。"]','理想信念的作用',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2020,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍中国举办第二届中国国际进口博览会的盛况，以及习近平主席在开幕式主旨演讲中关于共建开放合作、开放创新、开放共享的世界经济的主张。（公开文字版真题未附完整材料，此处为概述）
(1)阐述中国举办国际进口博览会的背景和意义。
(2)为什么说进博会“交易的是商品和服务，交流的是文化和理念”？','["阐述中国举办国际进口博览会的背景和意义。","为什么说进博会“交易的是商品和服务，交流的是文化和理念”？"]','["在保护主义抬头、世界经济增长放缓的背景下，中国主动扩大进口、举办进博会，是推动建设开放型世界经济的重大举措。","进博会为各国企业进入中国市场搭建平台，以中国大市场为世界提供共同发展机遇，彰显中国开放的大门越开越大。","进博会不仅促成商品和服务交易，更促进各国文明交流互鉴，传递开放合作、互利共赢的理念。","它体现了中国与世界共享发展机遇、推动构建人类命运共同体的价值追求。"]','高水平对外开放',1,0);
DELETE FROM real_subjective WHERE year=2021;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2021,34,'马原·哲学','结合材料回答问题：
材料概述：材料摘编2020年相关报道：面对新冠疫情冲击和百年未有之大变局，习近平总书记提出“在危机中育新机、于变局中开新局”，强调要准确识变、科学应变、主动求变；我国统筹疫情防控和经济社会发展，一些行业企业化危为机、逆势增长。
(1)分析“在危机中育新机、于变局中开新局”，这一论断蕴含的唯物辩证法原理。
(2)运用主观能动性与客观规律性相统一的原理，说明“主动求变”与“准确识变”之间的关系。','["分析“在危机中育新机、于变局中开新局”，这一论断蕴含的唯物辩证法原理。","运用主观能动性与客观规律性相统一的原理，说明“主动求变”与“准确识变”之间的关系。"]','["危与机是对立统一的矛盾双方，在一定条件下相互转化，“危机中育新机、变局中开新局”体现了矛盾同一性与斗争性辩证关系的原理。","事物发展是前进性与曲折性的统一，把握变化趋势、创造转化条件，就能化危为机。","尊重客观规律是发挥主观能动性的前提，“准确识变”就是认识和把握形势变化的客观规律。","“主动求变”是在把握规律基础上发挥主观能动性、积极应变创新，二者统一于改造世界的实践之中。"]','主观能动性与客观规律性',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2021,35,'毛中特','结合材料回答问题：
材料概述：材料1回顾从邓小平提出“小康之家”，到解决温饱、总体小康，再到全面建成小康社会的历史进程，2020年脱贫攻坚取得决定性成就；材料2摘编相关报道，引述习近平总书记“全面建成小康社会不是终点，而是新生活、新奋斗的起点”的论述。
(1)从人民生活水平不断提高的视角，分析我国从“解决温饱”到“达到小康水平”再到“全面建成小康社会”中所体现的中国特色社会主义制度优势。
(2)如何理解“全面建成小康社会不是终点，而是新生活，新奋斗的起点”？','["从人民生活水平不断提高的视角，分析我国从“解决温饱”到“达到小康水平”再到“全面建成小康社会”中所体现的中国特色社会主义制度优势。","如何理解“全面建成小康社会不是终点，而是新生活，新奋斗的起点”？"]','["从解决温饱到全面建成小康社会，人民生活的历史性跨越充分体现了党集中统一领导、集中力量办大事的制度优势。","坚持以人民为中心的发展思想、共同富裕方向和社会主义基本经济制度，是人民生活不断改善的根本保障。","五年规划接续实施、脱贫攻坚精准发力，展现了中国特色社会主义制度强大的组织动员和资源配置能力。","全面小康不是终点，我国社会主要矛盾尚未根本解决，人民对美好生活的向往不断提升。","站在新起点上要接续奋斗，开启全面建设社会主义现代化国家新征程，向共同富裕目标继续迈进。"]','共同富裕',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2021,36,'史纲','结合材料回答问题：
1950年6月25日，朝鲜内战爆发。美国政府从其全球战略和冷战思维出发，做出武装干涉朝鲜内战的决定，并派遣第七舰队驶入台湾海峡。1950年10月初，美军不顾中国政府一再警告，悍然越过三八线，把战火烧到中朝边境。侵朝美军飞机多次轰炸中国东北边境地区，给人民生命财产造成严重损失，我国安全面临严重威胁。值此危机关头，应朝鲜党和政府请求，中国党和政府以非凡气魄和胆略作出抗美援朝、保家卫国的历史性决策。1950年10月19日，中国人民志愿军在彭德怀司令员兼政治委员率领下进入朝鲜战场。
抗美援朝战争，是在交战双方力量极其悬殊条件下进行的一场现代化战争。当时，中美两国国力相差巨大。在这样极不对称、极为艰难的情况下，中国人民志愿军同朝鲜军民密切配合，首战两水洞、激战云山城、会战清川江、鏖战长津湖等，连续进行5次战役，此后又构筑起铜墙铁壁般的纵深防御阵地，实施多次进攻战役，粉碎“绞杀战”、抵御“细菌战”、血战上甘岭，创造了威武雄壮的战争伟业。全国各族人民由衷称赞志愿军将士为“最可爱的人”！经过艰苦卓绝的战斗，中朝军队打败了武装到牙齿的对手，打破了美军不可战胜的神话，迫使不可一世的侵略者于1953年7月27日在停战协定上签字。
在抗美援朝战争期间，党中央统揽全局，实施有力的战争动员和正确的战争指导，采取边打、边稳、边建的方针，开展了波澜壮阔的抗美援朝运动，全国各族人民举国同心支撑起这场事关国家和民族前途命运的伟大抗争，最终用伟大胜利向世界宣告“西方侵略者几百年来只要在东方一个海岸上架起几尊大炮就可霸占一个国家的时代是一去不复返了”！
抗美援朝战争伟大胜利，是中国人民站起来后屹立于世界东方的宣言书，是中华民族走向伟大复兴的重要里程碑，对中国和世界都有着重大而深远的意义。
摘自《在纪念中国人民志愿军抗美援朝出国作战70周年大会上的讲话》
(1)党和政府作出抗美援朝、保家卫国的历史性决策需要“非凡的气魄和胆略”。请结合新中国成立初期的形势和党的任务加以说明。
(2)为什么说抗美援朝战争伟大胜利“对中国和世界都有着重大而深远的意义”？','["党和政府作出抗美援朝、保家卫国的历史性决策需要“非凡的气魄和胆略”。请结合新中国成立初期的形势和党的任务加以说明。","为什么说抗美援朝战争伟大胜利“对中国和世界都有着重大而深远的意义”？"]','["新中国成立初期百废待兴，面临医治战争创伤、恢复国民经济、巩固新生政权的艰巨任务，敌我力量对比悬殊。","在这种形势下出兵参战，敢于同世界最强大的帝国主义国家较量，需要非凡的气魄和胆略。","党中央权衡利弊，从维护国家安全和东方与世界和平出发毅然决策，体现了战略远见。","抗美援朝的胜利打出了新中国的国威军威，为我国经济建设赢得了相对稳定的和平环境，极大增强了民族自信心。","胜利维护了亚洲和世界和平，打破了美军不可战胜的神话，鼓舞了世界被压迫民族争取独立解放的斗争。"]','中华人民共和国成立的意义',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2021,37,'思修法基','结合材料回答问题：
材料概述：材料讲述抗击新冠疫情的斗争：党中央统一指挥下，全国人民同心抗疫，各地医疗队驰援武汉，全国人民“为武汉热干面加油”；在抗疫斗争中铸就了生命至上、举国同心、舍生忘死、尊重科学、命运与共的伟大抗疫精神，广大青年在抗疫一线经受了考验。
(1)伟大抗疫精神是中国精神的生动诠释，“全国人民都‘为武汉热干面加油’”彰显了什么样的中国精神？
(2)伟大抗疫精神将激励新时代青年如何担当民族复兴的时代使命？','["伟大抗疫精神是中国精神的生动诠释，“全国人民都‘为武汉热干面加油’”彰显了什么样的中国精神？","伟大抗疫精神将激励新时代青年如何担当民族复兴的时代使命？"]','["“为武汉热干面加油”彰显了万众一心、同甘共苦的团结伟力，是以爱国主义为核心的民族精神的生动体现。","全国人民守望相助，体现了生命至上、举国同心、舍生忘死、尊重科学、命运与共的伟大抗疫精神。","伟大抗疫精神是中国精神在新时代的集中展现，丰富了民族精神和时代精神的内涵。","新时代青年应弘扬抗疫精神，厚植家国情怀、锤炼过硬本领，在担当中历练、在尽责中成长。","要把个人奋斗融入民族复兴伟业，在党和人民最需要的地方冲锋在前、贡献青春力量。"]','中国精神的内涵',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2021,38,'形势与政策','结合材料回答问题：
材料概述：材料1介绍美国政府奉行单边主义、相继退出多个国际组织和国际协议的情况；材料2介绍中国坚定维护以联合国为核心的国际体系，习近平主席在联合国成立75周年系列高级别会议上就全球治理提出坚持共商共建共享等“四点建议”。
(1)分析中国和美国政府对待国际组织和国际事务的差异，并指出这种差异的实质。
(2)所提的“四点建议”，对于后疫情时代全球治理体系改革和建设有何意义？','["分析中国和美国政府对待国际组织和国际事务的差异，并指出这种差异的实质。","所提的“四点建议”，对于后疫情时代全球治理体系改革和建设有何意义？"]','["中国坚定维护以联合国为核心的国际体系，积极参与国际抗疫合作，而美国奉行单边主义、频繁退群毁约。","这种差异的实质是多边主义与单边主义、合作共赢与霸权私利两种国际秩序观的对立。","“四点建议”倡导践行真正的多边主义，坚持开放包容、平等协商、合作共赢。","它为后疫情时代完善全球治理指明方向，有利于维护联合国权威、推动全球治理体系朝着更加公正合理的方向发展。"]','人类命运共同体',1,1);
DELETE FROM real_subjective WHERE year=2022;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2022,34,'马原·哲学','结合材料回答问题：
材料概述：材料1摘自《中共中央关于党的百年奋斗重大成就和历史经验的决议》相关内容：进入新时代，国家安全形势更为严峻，“黑天鹅”“灰犀牛”事件时有发生，必须坚持底线思维、统筹发展和安全；材料2摘编报道，讲述对小概率事件与重大风险防范关系的讨论。
(1)运用必然与偶然辩证关系的原理，说明小概率事件并非零概率事件。
(2)面对复杂局面应如何运用好辩证思维？','["运用必然与偶然辩证关系的原理，说明小概率事件并非零概率事件。","面对复杂局面应如何运用好辩证思维？"]','["必然性与偶然性是揭示事物发展确定趋势与不确定趋势的一对范畴，二者对立统一、相互依存并在一定条件下相互转化。","偶然性背后隐藏着必然性，小概率事件虽属偶然，但只要相关因素和条件具备就可能发生，故并非零概率事件。","“黑天鹅”“灰犀牛”警示我们必须坚持底线思维，居安思危、未雨绸缪，防范化解重大风险。","运用辩证思维应对复杂局面，就要在把握矛盾运动中统筹发展和安全，既抓住机遇又防范风险，提高驾驭复杂局面的能力。"]','必然性与偶然性',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2022,35,'毛中特','结合材料回答问题：
材料概述：材料摘编党的十九届六中全会相关报道：全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，把“坚持理论创新”概括为党百年奋斗的宝贵历史经验之一，指出党的历史就是一部不断推进理论创新、进行理论创造的历史，习近平新时代中国特色社会主义思想实现了马克思主义中国化新的飞跃。
(1)怎样认识我们党的历史“就是一部不断推进理论创新、进行理论创造的历史”?
(2)结合中华民族伟大复兴战略全局和世界百年未有之大变局，阐述如何理解习近平新时代中国特色社会主义思想“实现了马克思主义中国化新的飞跃”。','["怎样认识我们党的历史“就是一部不断推进理论创新、进行理论创造的历史”?","结合中华民族伟大复兴战略全局和世界百年未有之大变局，阐述如何理解习近平新时代中国特色社会主义思想“实现了马克思主义中国化新的飞跃”。"]','["党的百年历史就是不断把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合的历史。","党先后创立毛泽东思想、形成中国特色社会主义理论体系、创立习近平新时代中国特色社会主义思想，不断推进理论创新、进行理论创造。","实践没有止境、理论创新也没有止境，党坚持解放思想、实事求是，及时回答时代和人民之问。","习近平新时代中国特色社会主义思想立足中华民族伟大复兴战略全局和世界百年未有之大变局，系统回答了新时代的重大课题，是当代中国马克思主义、二十一世纪马克思主义，实现了马克思主义中国化新的飞跃。"]','两个结合',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2022,36,'史纲','结合材料回答问题：
材料概述：材料1摘自习近平在纪念孙中山先生诞辰150周年大会上的讲话：孙中山在《建国方略》中构想了修建约16万公里铁路、160万公里公路、开发三峡水利等建设中国的宏伟蓝图，但在旧中国的政治经济社会条件下难以实现，今天这些设想早已实现或超越；材料2摘编庆祝建党100周年报道，介绍党的百年奋斗的重大成就。
(1)为什么“在旧中国的政治经济社会条件下”，孙中山振兴中华的宏大构想“难以实现”？
(2)中国共产党百年奋斗的历史意义是什么？','["为什么“在旧中国的政治经济社会条件下”，孙中山振兴中华的宏大构想“难以实现”？","中国共产党百年奋斗的历史意义是什么？"]','["旧中国处于半殖民地半封建社会，帝国主义、封建主义压迫使国家四分五裂、经济凋敝，缺乏实现宏大建设构想的政治前提和物质条件。","没有民族独立和人民解放，没有先进阶级及其政党的领导，任何振兴中华的蓝图都难以实现。","党的百年奋斗从根本上改变了中国人民的前途命运，开辟了实现中华民族伟大复兴的正确道路。","党的百年奋斗展示了马克思主义的强大生命力，深刻影响了世界历史进程，锻造了走在时代前列的中国共产党。","今天孙中山设想的许多目标已经实现或超越，证明只有中国共产党才能领导中国实现现代化。"]','辛亥革命',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2022,37,'思修法基','结合材料回答问题：
材料概述：材料讲述“七一勋章”获得者黄文秀的事迹：她学成归来建设家乡，主动到贫困村担任驻村第一书记，带领群众修路通电、发展特色产业，使村庄贫困发生率大幅下降，2019年因公殉职，年仅30岁；材料还摘编习近平总书记对新时代青年担当使命的寄语。
(1)黄文秀的先进事迹启示新时代青年应该有怎样的人生态度?
(2)一代人有一代人的担当，新时代中国青年应当承担什么样的历史重任？','["黄文秀的先进事迹启示新时代青年应该有怎样的人生态度?","一代人有一代人的担当，新时代中国青年应当承担什么样的历史重任？"]','["黄文秀学成归来反哺家乡、把生命奉献给脱贫攻坚事业，启示青年应树立服务人民、奉献社会的科学人生观。","要以积极进取的人生态度面对人生，认真务实、乐观向上，在艰苦环境中磨砺成长。","新时代青年应担当实现中华民族伟大复兴的历史重任，增强做中国人的志气、骨气、底气。","要把个人理想融入党和人民的事业，到祖国和人民最需要的地方去，在全面建设社会主义现代化国家新征程中贡献青春力量。"]','为实现中国梦注入青春能量',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2022,38,'形势与政策','结合材料回答问题：
材料概述：材料1回顾联合国成立和新中国恢复联合国合法席位的历史：1971年第26届联大通过第2758号决议，恢复中华人民共和国在联合国的一切权利；材料2介绍习近平主席在纪念中华人民共和国恢复联合国合法席位50周年会议上的讲话，强调世界只有一个以联合国为核心的国际体系、一个以国际法为基础的国际秩序、一套以联合国宪章宗旨和原则为基础的国际关系基本准则。
(1)为什么说中华人民共和国恢复在联合国的一切权利“是中国人民的胜利，也是世界各国人民的胜利”？
(2)习近平主席所强调的世界只有“一个体系”“一个秩序”“一套规则”，对于推动构建人类命运共同体有何重要意义？','["为什么说中华人民共和国恢复在联合国的一切权利“是中国人民的胜利，也是世界各国人民的胜利”？","习近平主席所强调的世界只有“一个体系”“一个秩序”“一套规则”，对于推动构建人类命运共同体有何重要意义？"]','["恢复联合国合法席位使占世界人口近四分之一的中国人民重新走上联合国舞台，是中国人民长期斗争的胜利，也是世界正义力量共同努力的结果。","它极大增强了发展中国家在联合国的力量，改变了国际格局，故也是世界各国人民的胜利。","五十年来中国以实际行动维护联合国宪章宗旨和原则，成为世界和平与发展的重要建设性力量。","世界只有一个以联合国为核心的国际体系、一个以国际法为基础的国际秩序、一套以联合国宪章宗旨和原则为基础的国际关系基本准则，坚持这一共同标准才能防止阵营对立和“家法帮规”取代国际规则。","这为各国在多边框架内平等协商、合作应对全球性挑战提供了制度保障，是构建人类命运共同体的重要基础。"]','人类命运共同体',1,1);
DELETE FROM real_subjective WHERE year=2023;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2023,34,'马原·哲学','结合材料回答问题：
材料概述：材料介绍党的二十大报告关于建设农业强国、综合利用盐碱地的部署，讲述科研人员坚持系统观念，统筹土壤、盐分、微生物、作物品种、水利等因素，通过反复试验将“盐碱荒地”改造成“生态良田”的实践历程。
(1)从实践与认识的辩证运动角度，说明科学家将“盐碱荒地”改造成“生态良田”所体现的认识论原理。
(2)为什么盐碱地改良“必须坚持系统观念”？','["从实践与认识的辩证运动角度，说明科学家将“盐碱荒地”改造成“生态良田”所体现的认识论原理。","为什么盐碱地改良“必须坚持系统观念”？"]','["实践是认识的基础，科学家通过反复试验探索盐碱地治理办法，体现了认识来源于实践并接受实践检验。","认识运动是实践、认识、再实践、再认识循环往复以至无穷的辩证发展过程，改良技术在实践与认识的互动中不断完善。","从盐碱荒地到生态良田体现了认识指导实践、实践深化认识的能动的反映论原理。","事物是普遍联系的有机整体，土壤、水利、作物、生态各要素相互制约，改良盐碱地必须统筹兼顾。","坚持系统观念就是坚持普遍联系和整体性思维，注重协同性和综合施策，才能实现可持续的治理效果。"]','实践是认识的基础',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2023,35,'毛中特','结合材料回答问题：
材料概述：材料1摘编党的二十大相关报道：党的十八大以来，党中央统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局，党和国家事业取得历史性成就、发生历史性变革，全面建成小康社会；材料2摘自党的二十大关于十九届中央委员会报告的决议，涉及中国式现代化的理论和实践创新。
(1)分析新时作“年“党和国家事业取得历史性成就、发生历史性变革”所体现的以人民为中心的发展思想，
(2)中国式现代化是中国共产党和中国人民长期实践探索的成果，是一项伟大而艰巨的事业，结合党的十八大以来的理论和实践创新突破，分析新时代党怎样“成功推进和拓展了中国式现代化”。','["分析新时作“年“党和国家事业取得历史性成就、发生历史性变革”所体现的以人民为中心的发展思想，","中国式现代化是中国共产党和中国人民长期实践探索的成果，是一项伟大而艰巨的事业，结合党的十八大以来的理论和实践创新突破，分析新时代党怎样“成功推进和拓展了中国式现代化”。"]','["新时代党和国家事业取得历史性成就，根本在于坚持以人民为中心的发展思想，把人民对美好生活的向往作为奋斗目标。","脱贫攻坚全面胜利、民生保障不断加强、发展成果更多惠及全体人民，充分体现了发展为了人民、发展依靠人民、发展成果由人民共享。","党的十八大以来提出新发展理念、推动高质量发展、促进共同富裕，实现了理论和实践上的创新突破。","党成功推进和拓展了中国式现代化，使其具有人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路的中国特色。","中国式现代化为发展中国家走向现代化提供了全新选择。"]','中国式现代化',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2023,36,'史纲','结合材料回答问题：
材料 11945 年 4 月 21 日，毛泽东在党的七大预备会议上的报告中指出：
“我们大会的方针是什么呢？应该是：团结一致，争取胜利，简单讲，就是一个团结，一个胜利，胜利是指我们的目标，团结是指我们的阵线，我们的队伍，我们要有一个团结的队伍去打倒我们的敌人，争取胜利，而队伍中间最主要的、起领导作用的，是我们的党，没有我们的党，中国人民要胜利是不可能的。”
“过去常说，团结得像一个人一样，那是写文章的词藻，我们这回说，团结得像一个和睦的家庭一样。”“要知道，一个队伍经常是不大整齐的，所以就要常常喊看齐，向左看齐，向右看齐，向中看齐，我们要向中央基准看齐，向大会基准看齐，看齐是原则，有偏差是实际生活，有了偏差，就喊看齐。”
“在党内，在革命队伍内，我们有一条方针，就是团结，在原则基础上的团结。”
摘自《毛泽东文集》第三卷
材料 21978 年 12 月 13 日，邓小平在中央工作会议上的讲话中招出：
“这次会议开了一个多月了，就要结束了，中央提出了把全党工作的重心转到实现四个现代化上来的根本指导方针，解决了过去追留下来的一系列重大问题，必将使全党、全军和全国各族人民提高斗志、增强信心，加强团结。"
“加强全国各族人民的团结、首先委加强全党的固结、特别是委加强党的领导核心的团结，我们党的团结，是建立在马列主义、毛泽东思想基础上的函结.党内委分清理论是非、路线是非，要开展批评和自我批评，互相帮助，互相监督。克服各种错误思想。”
“只要我们大家团结一致，同心同德，解放思想，开动脑筋，学会原来不懂的东西，我们就一定能够加快新长征的步伐。让我们在党中央和国务院的领导下，为政党我国的落后面貌，把我国建设成现代化的社会主义强国而奋勇前进！”
摘自《邓小平文选》第二卷
材料 32022 年 1 月 30 日，习近平总书记在春节团拜会上的讲话中指出：
“一百年来，党和人民取得的一切成就都是因结奋斗的结果，团结奋斗是中国共产党和中国人民最显著的精神标识，百年奋斗历史告诉我们，团结就是力量，奋斗升创未来；能团结奋斗的民族才有前途，能团结奋斗的政党才能立于不败之地，百年奋斗历史还告诉我们，围绕明确奋斗目标形成的团结才是最牢固的团结，依靠紧密团结进行的奋斗才是最有力的奋斗。”
2022 年 10 月 16 日，习近平总书记在党的二十大报告中指出：
“全面建设社会主义现代化国家、全面推进中华民族伟大复兴，关键在党。”“全党必须牢记，坚持党的全面领导是坚持和发展中国特色社会主义的必由之路，中国特色社会主义是实现中华民族伟大复兴的必由之路，团结奋斗是中国人民创造历史伟业的必由之路，贯彻新发展理念是新时代我国发展壮大的必由之路，全面从严治党是党永葆生机活力、走好新的赶考之路的必由之路。”
“党用伟大奋斗创造了百年伟业，也一定能用新的伟大奋斗创造新的伟业，全党全军全国各族人民要紧密团结在党中央周围，牢记空谈误国、实干兴邦，坚定信心、同心同德，埋头苦干、奋勇前进，为全面建设社会主义现代化国家全面推进中华民族伟大复兴而团结奋斗！”
摘自《习近平谈治国理政》第四卷、习近平《高举中国特色社会主义伟大旗帜为全面建设社会主义现代化国家而团结奋斗————在中国共产党第二十次全国代表大会上的报告》
(1)结合当时的形势和党的任务，说明毛泽东强调“有了偏差，就喊看齐”的重要性。
(2)团结奋斗是中国共产党和中国人民最显著的精神标识。如何理解“一百年来，党和人民取得的一切成就都是团结奋斗的结果”？','["结合当时的形势和党的任务，说明毛泽东强调“有了偏差，就喊看齐”的重要性。","团结奋斗是中国共产党和中国人民最显著的精神标识。如何理解“一百年来，党和人民取得的一切成就都是团结奋斗的结果”？"]','["抗战胜利前夕，夺取民主革命全国胜利需要全党在思想上政治上组织上高度统一。","毛泽东强调“有了偏差，就喊看齐”，就是要求全党自觉向党中央看齐，纠正偏差、步调一致，为完成党的任务提供纪律保证。","党的团结统一是党的生命，是党领导人民战胜一切困难的根本保证。","一百年来，从革命、建设到改革，党紧紧依靠人民、组织动员人民，靠团结奋斗取得了一切成就。","新征程上仍须发扬团结奋斗精神，凝聚起全面建设社会主义现代化国家的磅礴力量。"]','抗日战争',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2023,37,'思修法基','结合材料回答问题：
材料概述：材料1摘编报道：屠呦呦、黄旭华等一代代科学家以科学报国的品行诠释了以爱国主义为底色的科学家精神，习近平总书记强调新征程上更需要继续发扬这种精神；材料2讲述“八一勋章”获得者钱七虎院士六十余年为国铸盾、创建现代防护工程理论体系的事迹。
(1)为什么新时代“更需要继续发扬以爱国主义为底色的科学家精神”？
(2)钱七虎为国铸盾的科学实践，对当代青年进行创新创造有何启示？','["为什么新时代“更需要继续发扬以爱国主义为底色的科学家精神”？","钱七虎为国铸盾的科学实践，对当代青年进行创新创造有何启示？"]','["科学无国界，科学家有祖国，爱国主义始终是科学家精神的底色和第一要义。","新时代实现高水平科技自立自强、突破关键核心技术，更需要科学家胸怀祖国、服务人民的精神支撑。","钱七虎把毕生献给国防工程事业，体现了把个人理想融入国家需要的价值追求。","当代青年应志存高远、勇攀高峰，把创新创造与国家战略需求结合起来。","要发扬求实创新、艰苦奋斗精神，甘坐冷板凳，在创新实践中锤炼真本领、作出真贡献。"]','爱国主义的时代要求',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2023,38,'形势与政策','结合材料回答问题：
材料概述：材料1介绍2022年联合国宣布世界人口达80亿，古特雷斯秘书长指出人类大家庭壮大的同时不平等加剧，粮食、能源危机冲击发展中国家，世界又一次站在历史的十字路口；材料2摘编报道，介绍中国通过共建“一带一路”、全球发展倡议等帮助发展中国家共同发展的贡献。
(1)为什么说“世界又一次站在历史的十字路口”？
(2)中国在帮助发展中国家共同发展方面所作的巨大贡献，体现出怎样的外交理念与大国担当？','["为什么说“世界又一次站在历史的十字路口”？","中国在帮助发展中国家共同发展方面所作的巨大贡献，体现出怎样的外交理念与大国担当？"]','["世界之变、时代之变、历史之变正以前所未有的方式展开，和平与发展面临单边主义、阵营对抗等严峻挑战，人类社会面临何去何从的抉择，故说世界又一次站在历史的十字路口。","团结合作还是分裂对抗、开放还是封闭，关系人类前途命运。","中国通过共建“一带一路”、落实全球发展倡议、免债减债和援助合作等，帮助发展中国家增强自主发展能力。","这体现了中国坚持真正的多边主义、践行共商共建共享的全球治理观，展现了构建人类命运共同体的大国担当。"]','三大全球倡议',1,1);
DELETE FROM real_subjective WHERE year=2024;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2024,34,'马原·哲学','结合材料回答问题：
材料概述：材料摘编大兴调查研究相关报道：党中央把大兴调查研究作为主题教育重要内容，习近平总书记强调既要学会调查也要擅长研究，在调查基础上深化研究，把调研成果转化为解决问题的实际举措；材料还讲述通过解剖典型案例“解决一个问题”推动“解决一类问题”的工作方法。
(1)如何理解“调查是全面、客观、准确掌握情况的过程，并不自然产生科学观点、得出正确结论”?
(2)为什么“解决一个问题”能推动“解决一类问题”?','["如何理解“调查是全面、客观、准确掌握情况的过程，并不自然产生科学观点、得出正确结论”?","为什么“解决一个问题”能推动“解决一类问题”?"]','["调查获得的感性材料是认识的基础，但感性认识有待于上升为理性认识，掌握情况不等于形成科学观点。","从感性到理性的飞跃需要运用科学思维方法对材料去粗取精、去伪存真、由此及彼、由表及里地加工制作，这就是“研究”的功夫。","矛盾的普遍性寓于特殊性之中，通过解剖典型解决一个问题，可以揭示同类问题的共同本质和规律。","把个别经验上升为一般规律再指导面上工作，体现了从特殊到普遍、再由普遍到特殊的认识秩序，故能推动“解决一类问题”。"]','感性认识与理性认识',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2024,35,'毛中特','结合材料回答问题：
材料概述：材料摘编生态文明建设相关报道：党的十八大以来，在习近平生态文明思想指引下，塞罕坝沙地变林海、苍山洱海恢复本色等中国故事见证生态文明建设的历史性变化；党的二十大对以高品质生态环境支撑高质量发展、加快推进人与自然和谐共生的现代化作出部署。
(1)如何理解“以高品质生态环境支撑高质量发展，加快推进人与自然和谐共生的现代化”?
(2)从人与自然和谐共生的现代化角度，分析中国式现代化道路的世界意义。','["如何理解“以高品质生态环境支撑高质量发展，加快推进人与自然和谐共生的现代化”?","从人与自然和谐共生的现代化角度，分析中国式现代化道路的世界意义。"]','["高品质生态环境是高质量发展的内在要求和重要支撑，绿水青山就是金山银山。","以高品质生态环境支撑高质量发展，就是协同推进降碳、减污、扩绿、增长，把生态优势转化为发展优势。","人与自然和谐共生的现代化摒弃了先污染后治理的老路，实现了发展与保护的统一。","中国式现代化为广大发展中国家提供了绿色低碳发展的新路径，超越了西方以牺牲环境为代价的现代化模式。","中国积极参与全球环境治理、推动落实“双碳”目标，为共建清洁美丽世界贡献了中国智慧和中国力量。"]','中国式现代化',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2024,36,'史纲','结合材料回答问题：
材料概述：材料1摘自《复兴文库》：1919年陈独秀撰文拥护“德先生”（民主）与“赛先生”（科学），主张反对旧伦理、旧政治、旧文学；材料2摘自《毛泽东选集》第2卷关于新民主主义文化即民族的科学的大众的文化的论述；材料3摘自《求是》2023年第17期，介绍习近平总书记在文化传承发展座谈会上关于“第二个结合”、建设中华民族现代文明和破解“古今中西之争”的重要论述。
(1)结合新文化运动以来的历史，分析中国共产党对中国文化发展方向的探索及其意义。
(2)为什么说“我们比以往任何一个时代都更有条件破解‘古今中西之争’”?','["结合新文化运动以来的历史，分析中国共产党对中国文化发展方向的探索及其意义。","为什么说“我们比以往任何一个时代都更有条件破解‘古今中西之争’”?"]','["新文化运动以来，中国共产党在探索中回答了中国文化向何处去的问题，坚持以马克思主义为指导改造和发展中国文化。","党坚持把马克思主义基本原理同中华优秀传统文化相结合，推动传统文化创造性转化、创新性发展。","从新民主主义文化纲领到中国特色社会主义文化建设，党指明了民族的科学的大众的文化发展方向，为民族复兴提供了精神支撑。","新时代我们创造了人类文明新形态，文化自信显著增强，物质技术条件和制度保障更加坚实。","“第二个结合”巩固了文化主体性，使我们比以往任何时代都更有条件破解“古今中西之争”，建设中华民族现代文明。"]','两个结合',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2024,37,'思修法基','结合材料回答问题：
材料概述：材料1摘编习近平总书记给中国农业大学科技小院学生的回信报道：总书记肯定青年人“自找苦吃”的精气神；材料2讲述河南林县人民在艰苦条件下修建红旗渠的历史，以及新时代青年在基层一线经受磨炼、担当作为的事例。
(1)从实现理想的角度，说明“越是美好的梦想，越需要发扬‘自找苦吃’的精神”。
(2)从创造有意义人生的角度，分析新时代青年如何在“自找苦吃”中“收获成功”。','["从实现理想的角度，说明“越是美好的梦想，越需要发扬‘自找苦吃’的精神”。","从创造有意义人生的角度，分析新时代青年如何在“自找苦吃”中“收获成功”。"]','["理想的实现具有长期性、艰巨性和曲折性，越是美好的梦想越需要艰苦奋斗去争取。","“自找苦吃”体现了实现理想必须付出艰辛努力的自觉，是砥砺意志、锤炼本领的必由之路。","艰苦奋斗是中华民族的优良传统，也是青年成长成才的精神养分。","人生的意义在于奉献和创造，青年在服务人民、艰苦奋斗中才能创造有意义的人生。","新时代青年应到基层和艰苦环境中经受磨炼，把吃苦转化为成长的财富，在奋斗中收获成功、实现人生价值。"]','理想信念的作用',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2024,38,'形势与政策','结合材料回答问题：
材料概述：材料介绍共建“一带一路”十周年成就：基础设施“硬联通”、规则标准“软联通”成果丰硕，安哥拉供水等“小而美”民生项目让共建国家民众获得实实在在的幸福感，实现了民心相通；材料还摘编相关报道，讨论讲好中国故事、让国际社会更好理解“一带一路”倡议的问题。
(1)共建“一带一路”,为什么既能实现路和桥等基础设施的“硬联通”、规则标准的“软联通”,也能架起世界各国人民“心联通”的桥梁?
(2)“让国际社会更好地理解共建‘一带一路’倡议”对于我们讲好中国故事、提升国际传播能力有何启示？','["共建“一带一路”,为什么既能实现路和桥等基础设施的“硬联通”、规则标准的“软联通”,也能架起世界各国人民“心联通”的桥梁?","“让国际社会更好地理解共建‘一带一路’倡议”对于我们讲好中国故事、提升国际传播能力有何启示？"]','["共建“一带一路”坚持共商共建共享原则，基础设施“硬联通”和规则标准“软联通”给共建国家带来实实在在的发展成果。","“小而美”的民生项目直接惠及当地民众，增进了民生福祉，赢得民心认同，架起“心联通”的桥梁。","文明互鉴、人文交流使共建国家人民相知相亲，共同的发展愿景凝聚起广泛共识。","讲好中国故事要用事实说话，以共建国家人民的获得感展示倡议的真实成效。","提升国际传播能力应贴近不同受众、创新话语表达，增强中国声音的亲和力和说服力。"]','高质量共建一带一路',1,1);
DELETE FROM real_subjective WHERE year=2025;
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2025,34,'马原·哲学','结合材料回答问题：
材料概述：材料1摘自《马克思恩格斯文集》第九卷恩格斯关于认识的相对性与真理谬误辩证关系的论述：认识对漫长的世代系列来说是逐步趋于完善的，真理和谬误只是在非常有限的领域内才具有绝对意义；材料2摘编报道，介绍改革方法论中加强顶层设计和摸着石头过河“两手并用”的实践。
(1)如何理解“认识就其本性而言，或者对漫长的世代系列来说是相对的而且必然是逐步趋于完善的，或者……由于历史材料不足，甚至永远是有缺陷的和不完善的”？
(2)试说明加强顶层设计和摸着石头过河“两手并用”蕴含着的“知”和“行”的辩证关系。','["如何理解“认识就其本性而言，或者对漫长的世代系列来说是相对的而且必然是逐步趋于完善的，或者……由于历史材料不足，甚至永远是有缺陷的和不完善的”？","试说明加强顶层设计和摸着石头过河“两手并用”蕴含着的“知”和“行”的辩证关系。"]','["恩格斯这一论断揭示了真理的绝对性与相对性的统一，人的认识能力无限与有限的矛盾决定认识是一个不断完善的过程。","任何真理都是对客观世界一定层次、一定程度的正确反映，受历史条件和实践水平的制约，因而是有限度的、有待深化的。","实践与认识辩证统一，“行”是“知”的来源和目的，“知”对“行”具有能动的指导作用。","摸着石头过河强调从实践中获得认识，顶层设计强调以科学认识指导实践，两手并用体现了知行合一、实践与认识的辩证运动。","这要求我们在改革中坚持实践第一，在实践中深化认识，用不断发展的认识指导新的实践。"]','真理的绝对性与相对性',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2025,35,'毛中特','结合材料回答问题：
材料概述：材料1摘编报道：党的十八大以来党中央坚持制度建设主线，推动新时代全面深化改革取得重大制度成果，书写了“中国之制”新篇章；材料2摘自习近平《开创我国高质量发展新局面》，强调谋划进一步全面深化改革重大举措，为推动高质量发展、推进中国式现代化持续注入强劲动力。
(1)如何理解“新时代全面深化取得重大制度成果，书写了‘中国之制’新篇章”？
(2)进一步全面深化改革为什么能够为推动高质量发展、推进中国式现代化持续注入强劲动力？','["如何理解“新时代全面深化取得重大制度成果，书写了‘中国之制’新篇章”？","进一步全面深化改革为什么能够为推动高质量发展、推进中国式现代化持续注入强劲动力？"]','["新时代全面深化改革坚持制度建设主线，完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化，取得历史性的制度成果。","各领域基础性制度框架基本建立，许多领域实现历史性变革、系统性重塑、整体性重构，书写了“中国之制”新篇章。","改革是发展的动力，进一步全面深化改革能够破除制约高质量发展的体制机制障碍。","构建高水平社会主义市场经济体制、健全宏观经济治理体系，能激发各类经营主体活力、促进新质生产力发展。","以制度建设保障科技创新、扩大高水平对外开放，为中国式现代化持续注入强劲动力。"]','全面深化改革与进一步全面深化改革',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2025,36,'史纲','结合材料回答问题：
材料 1：
1938 年 5 月 26 日至 6 月 3 日，毛泽东在延安抗日战争研究会发表题为《论持久战》的讲演。毛泽东指出：
“中日战争不是任何别的战争，乃是半殖民地半封建的中国和帝国主义之间的日本之间在 20 世纪 30 年代进行的一个决死的战争。”
“在什么条件下，中国能战胜并消灭日本帝国主义的实力呢？要有三个条件： 第一是中国抗日统一战线的完成，第二是国际抗日统一战线的完成；第三是日本国内人民和日本殖民地人民的革命运动的兴起：就中国人民的立场来说，三个条件中，中国人民的联合是主要的，这个战争要延长多久呢？要看中国抗日统一战线的实力和中国日两国其他许多因素如何而定的。如果这些条件不能很快实现，战争就要延长，结果还是一样，日本必败，中国必胜。”
摘自《毛泽东选集》第三卷
材料 22020 年 9 月 3 日，习近平总书记在纪念中国人民抗日战争暨世界反法西斯战争胜利 75 周年座谈会上的讲话中指出：
“这是近代以来中国人民反抗外敌入侵持续时间最长、规模最大、牺牲最多的民族解放斗争，也是第一次取得完全胜利的民族解放斗争。
这个伟大胜利，是中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点、也是世界反法西斯战争胜利的重要组成部分，是中国人民的胜利，也是世界人民的胜利。”
“在抗日战争时期，在民族危亡的历史关头，中国共产党以卓越的政治领导力和正确的战略策略，指引了中国抗战的前进方向，坚定不移推动全民族坚持抗战、团结、进步，反对妥协、分裂、倒退。中国共产党高举抗日民族统一战线的旗帜，坚决维护、巩固、发展统一战线，坚持独立自主、团结抗战，维护了团结抗战大局。中国共产党人勇敢战斗在抗日战争最前线，支撑起中华民族救亡图存的希望，成为全民族抗战的中流砥柱！”
摘自 习近平《论中国共产党历史》
(1)如何理解“就广大中国人民的立场来说” ，“中国人民的大联合”是战败并消灭日本帝国主义的主要条件。
(2)抗日战争的胜利对中华民族从近代以来陷入深重危机走向伟大复兴有何历史意义？','["如何理解“就广大中国人民的立场来说” ，“中国人民的大联合”是战败并消灭日本帝国主义的主要条件。","抗日战争的胜利对中华民族从近代以来陷入深重危机走向伟大复兴有何历史意义？"]','["抗日战争是全民族的战争，只有动员和依靠全体中国人民，实行全面抗战路线，才能战胜日本帝国主义。","中国共产党倡导建立抗日民族统一战线，实现了空前的民族大团结，“中国人民的大联合”成为战胜敌人的主要条件。","人民群众是历史的创造者，战争伟力最深厚的根源存在于民众之中。","抗战胜利是近代以来中国抗击外敌入侵的第一次完全胜利，洗雪了民族耻辱，捍卫了国家主权。","胜利重新确立了中国的大国地位，增强了民族自尊心自信心，为中华民族从深重危机走向伟大复兴确立了历史转折点。"]','抗日战争',1,0);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2025,37,'思修法基','结合材料回答问题：
材料概述：材料讲述我国防沙治沙的动人故事：塞罕坝几代人把风沙肆虐的荒原变成百万亩林海，八步沙“六老汉”三代人接续治沙，老干部杨善洲退休后义务植树22年，治沙实践证明治沙人种下的不仅是一棵棵树，更是一种信念、一种精神。
(1)如何理解“治沙人种下的不仅是一棵棵树，更是一种信念，一种精神”？
(2)在干事创业中，新时代青年应从治沙人的事迹中汲取怎样的力量？','["如何理解“治沙人种下的不仅是一棵棵树，更是一种信念，一种精神”？","在干事创业中，新时代青年应从治沙人的事迹中汲取怎样的力量？"]','["治沙人种树体现了坚定的理想信念，信念使人在漫长艰苦的事业中矢志不渝。","一代代治沙人接续奋斗铸就的艰苦奋斗、久久为功精神，是中国精神在生态治理领域的生动体现。","崇高的信念能够转化为改造客观世界的持久力量，把“不可能”变为现实。","新时代青年应从治沙人身上汲取坚守与担当的力量，树立正确的劳动观念，尊重劳动、热爱劳动。","在干事创业中要脚踏实地、迎难而上，以钉钉子精神做好本职工作，在长期奋斗中成就事业。"]','理想信念的作用',1,1);
INSERT INTO real_subjective (year,seq,subject,stem,questions,answer_points,kp_name,kp_confidence,third_party_material) VALUES (2025,38,'形势与政策','结合材料回答问题：
材料概述：材料1摘自《习近平著作选读》第二卷：数字经济发展速度之快、辐射范围之广、影响程度之深前所未有，正在成为重组全球要素资源、重塑全球经济结构、改变全球竞争格局的关键力量；材料2摘编报道，介绍“数字丝绸之路”建设和习近平主席在世界互联网大会乌镇峰会上关于推动网络空间创新发展、安全发展、普惠发展的主张。
(1)如何理解数字经济“正在成为重组全球要素资源、重塑全球经济结构、改变全球竞争格局的关键力量”？
(2)弥补“数字鸿沟”，迈进更加美好的“数字未来”，为什么要“加快推动网络空间创新发展、安全发展、普惠发展”？','["如何理解数字经济“正在成为重组全球要素资源、重塑全球经济结构、改变全球竞争格局的关键力量”？","弥补“数字鸿沟”，迈进更加美好的“数字未来”，为什么要“加快推动网络空间创新发展、安全发展、普惠发展”？"]','["数字技术全面融入经济社会发展，数据成为新的关键生产要素，数字经济深刻改变资源配置方式和产业组织形态。","数字经济正在重塑全球产业链、价值链和创新版图，成为重组全球要素资源、改变全球竞争格局的关键力量。","各国数字化发展水平差异形成“数字鸿沟”，制约全球共同发展和数字红利的公平分享。","推动网络空间创新发展才能培育增长新动能，安全发展才能应对数据安全和网络安全挑战，普惠发展才能让各国人民共享数字化成果。","中国倡导构建网络空间命运共同体，为弥合数字鸿沟、迈向美好数字未来提供了方案。"]','人类命运共同体',1,1);
